/* style.css — Build 9M-Detail | 35 layers | 2026 */

/* ==========================================================
   00_tokens.css — Global design tokens
   ========================================================== */

:root {
  /* ── Semantic text-on-surface ── */
  --ui-t5-main-on-secondary: rgb(255, 255, 255);
  --ui-t6-main-on-tertiary:  rgb(77, 177, 255);
  --ui-t7-selected-text:     rgb(0, 87, 210);
  --ui-t8-main-on-header:    rgb(34, 53, 72);
  --ui-t9-secondary-on-header: rgb(71, 94, 117);
  --ui-t10-tertiary-on-header: rgb(91, 115, 139);
  --ui-t11-cta-on-header:    rgb(0, 112, 242);
  --ui-b4-light-selected-border: rgb(0, 112, 242);

  /* ── Brand / semantic aliases ── */
  --chk-brand:           var(--ui-t4-cta-on-primary);
  --semantic-success:    var(--ui-sem-positive-label);
  --semantic-danger:     var(--ui-sem-negative-label);

  /* ── Feedback text (always uses adaptive text-main for contrast) ── */
  --feedback-info-text:    var(--text-main);
  --feedback-success-text: var(--text-main);
  --feedback-warning-text: var(--text-main);
  --feedback-error-text:   var(--text-main);

  /* ── Control text (high-contrast on colored backgrounds) ── */
  --control-primary-text: rgb(247, 251, 255);
  --control-danger-text:  rgb(255, 247, 247);
  --control-success-text: rgb(245, 255, 248);

  /* ── Text-strong (missing variable — maps to ui-t1 for both themes) ── */
  --text-strong: var(--ui-t1-main-on-primary);

  /* ── Border radii ── */
  --radius-xs: 0.65rem;
  --radius-sm: 0.9rem;
  --radius-xl: 1.9rem;

  /* ── Shadows ── */
  --shadow-soft: 0 14px 42px rgba(15, 28, 52, 0.12);
  --shadow-deep: 0 22px 60px rgba(12, 24, 44, 0.16);

  /* ── Visual effects ── */
  --glass-blur: 24px;

  /* ── Animation ── */
  --feedback-enter-duration:    260ms;
  --feedback-enter-ease:        cubic-bezier(0.22, 0.61, 0.36, 1);
  --feedback-pulse-duration:    1360ms;
  --feedback-attention-duration: 1600ms;

  /* ── Stack component ── */
  --chk-stack-gap: 1px;

  /* ── Table typography ── */
  --theme-table-header-line-height: 1.2;
  --theme-table-body-line-height:   1.38;
  --theme-table-row-radius:         0.88rem;

  /* ── Shell geometry ── */
  --app-shell-height: 4.75rem;
  --app-shell-offset: 6.5rem;

  /* ── Sticky position pre-computed offsets (set by JS but safe defaults) ── */
  --search-sticky-action-top:          var(--app-shell-offset);
  --search-sticky-dock-top:            var(--app-shell-offset);
  --search-sticky-filter-top:          var(--app-shell-offset);
  --search-sticky-table-toolbar-top:   var(--app-shell-offset);
  --search-sticky-toolbar-top:         var(--app-shell-offset);
  --search-workbench-toolbar-stack-height: 0px;

  /* ── Status chip (set per-row by JS, safe transparent defaults) ── */
  --status-chip-bg:     transparent;
  --status-chip-border: transparent;
  --status-chip-glow:   transparent;

  /* ── Flood / gradient origin ── */
  --theme-flood-x:      100vw;
  --theme-flood-y:      0px;
  --theme-flood-origin: 100vw 0px;

  /* ── Rate bar (per-element, safe default) ── */
  --rate-pct:        0%;
  --rate-fill-color: var(--accent, #0070f2);

  /* ── Accent switch states (per-element) ── */
  --accent-switch-bg:     var(--ui-s7-switch, rgb(91, 115, 139));
  --accent-switch-border: var(--ui-b5-border-switch, rgb(91, 115, 139));

  /* ── sapNegative alias (UI5 native token bridge) ── */
  --sapNegative: var(--ui-sem-negative-label, rgb(210, 10, 10));

  /* ── Spacing custom props (used inline via --mx/--my) ── */
  --mx: 0;
  --my: 0;

  /* ── Responsive layout widths ── */
  --layout-sidebar-width:     22rem;
  --layout-content-max-width: 96rem;
  --layout-padding-inline:    clamp(0.75rem, 2vw, 1.5rem);
}

