:root {
  --appSkeletonBase: rgba(196, 210, 232, 0.55);
  --appSkeletonHighlight: rgba(255, 255, 255, 0.7);
  --appSkeletonBorder: rgba(180, 198, 224, 0.36);
}

body.chkAppRoot.appDark,
:root.chkAppRoot:not(.light-mode) {
  --appSkeletonBase: rgba(71, 92, 122, 0.58);
  --appSkeletonHighlight: rgba(183, 205, 239, 0.22);
  --appSkeletonBorder: rgba(120, 149, 196, 0.22);
}

.appSkeleton {
  position: relative;
  overflow: hidden;
  border-radius: 999px;
  will-change: background-position;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0) 0%, var(--appSkeletonHighlight) 50%, rgba(255, 255, 255, 0) 100%),
    linear-gradient(90deg, var(--appSkeletonBase) 0%, rgba(255, 255, 255, 0.08) 48%, var(--appSkeletonBase) 100%);
  background-size: 210% 100%, 100% 100%;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  animation: appSkeletonShimmer 1.8s linear infinite;
}

.appSkeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(100deg, rgba(255, 255, 255, 0) 18%, rgba(255, 255, 255, 0.22) 48%, rgba(255, 255, 255, 0) 78%);
  transform: translateX(-120%);
  animation: appSkeletonSweep 1.8s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

.appSkeletonReveal {
  animation: appSkeletonRevealFade 380ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
  transform-origin: 50% 50%;
  will-change: opacity, transform, filter;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(1),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(1) {
  animation-delay: 0ms;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(2),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(2) {
  animation-delay: 30ms;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(3),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(3) {
  animation-delay: 60ms;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(4),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(4) {
  animation-delay: 90ms;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(5),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(5) {
  animation-delay: 120ms;
}

.chkApp .searchAnalyticsRailGrid .appSkeletonReveal:nth-child(6),
.chkApp .searchAnalyticsBreakdownGrid .appSkeletonReveal:nth-child(6) {
  animation-delay: 150ms;
}

.appSkeletonLine {
  height: 0.8rem;
}

.appSkeletonLineShort {
  width: 30%;
  animation-delay: -0.18s;
}

.appSkeletonLineMedium {
  width: 55%;
  animation-delay: -0.36s;
}

.appSkeletonLineLong {
  width: 82%;
  animation-delay: -0.54s;
}

.appSkeletonList,
.appSkeletonFormSection,
.appSkeletonTableShell,
.appSkeletonMushroomCard {
