  box-shadow: var(--shadow-soft);
}

.appSkeletonFormSection,
.appSkeletonTableShell {
  padding: 1rem;
}

.appSkeletonTableHeader,
.appSkeletonTableRow {
  display: grid;
  grid-template-columns: 0.35fr 1.6fr 0.8fr 1.4fr 0.45fr;
  gap: 0.75rem;
  align-items: center;
}

.appSkeletonTableRows {
  display: grid;
  gap: 0.75rem;
  margin-top: 0.85rem;
}

@keyframes appSkeletonShimmer {
  0% { background-position: 140% 50%, 0 0; }
  100% { background-position: -40% 50%, 0 0; }
}

@keyframes appSkeletonSweep {
  0% { transform: translateX(-120%); opacity: 0; }
  14% { opacity: 0.95; }
  100% { transform: translateX(140%); opacity: 0; }
}

@keyframes appSkeletonRevealFade {
  0% {
    opacity: 0;
    transform: translateY(0.24rem) scale(0.992);
    filter: saturate(0.92) blur(2px);
  }

  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: saturate(1) blur(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .appSkeleton,
  .appSkeleton::after,
  .appSkeletonReveal {
    animation: none;
  }
}

