/* ══════════════════════════════════════════════════════════════
   CH 1 · SAP HORIZON ACCENT TOKENS PER THEME
   Light  = Morning Star  #0070F2  rgb(0,112,242)
   Dark   = Evening Horizon #4DB1FF rgb(77,177,255)
   ══════════════════════════════════════════════════════════════ */

body.chkAppRoot.appLight {
  --hz-accent:           #0070F2;
  --hz-accent-rgb:       0, 112, 242;
  --hz-accent-deep:      #0058C8;
  --hz-accent-tint:      rgba(0, 112, 242, 0.08);
  --hz-accent-border:    rgba(0, 112, 242, 0.30);

  --hz-success:          #1A7C40;
  --hz-success-rgb:      26, 124, 64;
  --hz-success-tint:     rgba(26, 124, 64, 0.07);
  --hz-success-border:   rgba(26, 124, 64, 0.32);

  --hz-danger:           #CC0000;
  --hz-danger-rgb:       204, 0, 0;
  --hz-danger-tint:      rgba(204, 0, 0, 0.07);
  --hz-danger-border:    rgba(204, 0, 0, 0.30);

  --hz-warning:          #C35500;
  --hz-warning-rgb:      195, 85, 0;
  --hz-warning-tint:     rgba(195, 85, 0, 0.07);
  --hz-warning-border:   rgba(195, 85, 0, 0.30);

  /* Switch */
  --hz-sw-on-bg:         linear-gradient(135deg, #0070F2 0%, #0058C8 100%);
  --hz-sw-on-rgb:        0, 112, 242;
  --hz-sw-off-bg:        rgba(218, 230, 248, 0.82);
  --hz-sw-off-border:    rgba(120, 162, 216, 0.52);

  /* Input surface — semi-transparent, blends into white card */
  --hz-in-bg:            rgba(255, 255, 255, 0.44);
  --hz-in-bg-hover:      rgba(255, 255, 255, 0.70);
  --hz-in-bg-focus:      rgba(255, 255, 255, 0.90);
  --hz-in-border:        rgba(118, 162, 218, 0.50);
  --hz-in-ring:          rgba(0, 112, 242, 0.16);
}

body.chkAppRoot.appDark {
  --hz-accent:           #4DB1FF;
  --hz-accent-rgb:       77, 177, 255;
  --hz-accent-deep:      #39A8FF;
  --hz-accent-tint:      rgba(77, 177, 255, 0.10);
  --hz-accent-border:    rgba(77, 177, 255, 0.26);

  --hz-success:          #5DC122;
  --hz-success-rgb:      93, 193, 34;
  --hz-success-tint:     rgba(93, 193, 34, 0.10);
  --hz-success-border:   rgba(93, 193, 34, 0.28);

  --hz-danger:           #FF5C77;
  --hz-danger-rgb:       255, 92, 119;
  --hz-danger-tint:      rgba(255, 92, 119, 0.10);
  --hz-danger-border:    rgba(255, 92, 119, 0.28);

  --hz-warning:          #FFB300;
  --hz-warning-rgb:      255, 179, 0;
  --hz-warning-tint:     rgba(255, 179, 0, 0.10);
  --hz-warning-border:   rgba(255, 179, 0, 0.28);

  /* Switch */
  --hz-sw-on-bg:         linear-gradient(135deg, #4DB1FF 0%, #39A8FF 100%);
  --hz-sw-on-rgb:        77, 177, 255;
  --hz-sw-off-bg:        rgba(16, 28, 50, 0.88);
  --hz-sw-off-border:    rgba(77, 177, 255, 0.18);

  /* Input surface — blends into dark card */
  --hz-in-bg:            rgba(10, 20, 38, 0.38);
  --hz-in-bg-hover:      rgba(16, 28, 50, 0.60);
  --hz-in-bg-focus:      rgba(20, 34, 58, 0.80);
  --hz-in-border:        rgba(77, 177, 255, 0.16);
  --hz-in-ring:          rgba(77, 177, 255, 0.18);
}

/* Light + Inverted blocks */
body.chkAppRoot.appLight.appInvertedBlockScheme {
  --hz-accent:           #70BAFF;
  --hz-accent-rgb:       112, 186, 255;
  --hz-accent-border:    rgba(112, 186, 255, 0.34);
  --hz-in-bg:            rgba(255, 255, 255, 0.06);
  --hz-in-bg-hover:      rgba(255, 255, 255, 0.10);
  --hz-in-bg-focus:      rgba(255, 255, 255, 0.15);
  --hz-in-border:        rgba(140, 196, 255, 0.26);
  --hz-in-ring:          rgba(112, 186, 255, 0.20);
}

/* Dark + Inverted blocks */
body.chkAppRoot.appDark.appInvertedBlockScheme {
  --hz-accent:           #0058C8;
  --hz-accent-rgb:       0, 88, 200;
  --hz-accent-border:    rgba(0, 88, 200, 0.28);
  --hz-in-bg:            rgba(0, 0, 0, 0.04);
  --hz-in-bg-hover:      rgba(0, 0, 0, 0.07);
  --hz-in-bg-focus:      rgba(0, 88, 200, 0.06);
  --hz-in-border:        rgba(0, 88, 200, 0.22);
  --hz-in-ring:          rgba(0, 88, 200, 0.16);
}

/* ══════════════════════════════════════════════════════════════
   CH 2 · SEGMENT BUTTON — CLOSED CONTOUR
   Key: outer track = overflow:hidden → children clipped to pill.
   BtnInner = border-radius:0 → track clips outer corners.
   Separator = border-right on each btn (not on last).
   Override both generic .sapMSegB and the specific
   .resultSegmentControl.sapMSegB from 40_page_search.css
   ══════════════════════════════════════════════════════════════ */

/* ── Track ── */
.chkApp .sapMSegB,
.chkApp .searchFilterExperienceShell .resultSegmentControl.sapMSegB {
  display:       inline-flex !important;
  align-items:   stretch !important;
  gap:           0 !important;
  padding:       0 !important;          /* kill 0.1rem padding from search */
  border-radius: 999px !important;
  border:        1.5px solid !important;
  overflow:      hidden !important;     /* ← THE FIX: clip children → closed contour */
  box-shadow:    none !important;
  position:      relative !important;
  width:         auto !important;       /* don't inherit 12.6rem */
}

body.chkAppRoot.appLight .chkApp .sapMSegB,
body.chkAppRoot.appLight .chkApp .searchFilterExperienceShell .resultSegmentControl.sapMSegB {
  background:   rgba(242, 247, 255, 0.92) !important;
  border-color: rgba(118, 162, 218, 0.48) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSegB,
body.chkAppRoot.appDark .chkApp .searchFilterExperienceShell .resultSegmentControl.sapMSegB {
  background:   rgba(14, 26, 48, 0.90) !important;
  border-color: rgba(77, 177, 255, 0.16) !important;
}

/* ── Each segment button ── */
.chkApp .sapMSegBBtn,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn {
  display:         flex !important;
  align-items:     stretch !important;
  flex:            1 1 auto !important;
  border:          0 !important;
  border-right:    1px solid !important;  /* separator */
  border-radius:   0 !important;          /* track clips outer corners */
  background:      transparent !important;
  cursor:          pointer !important;
  padding:         0 !important;
  margin:          0 !important;
  min-width:       3rem !important;
  transition:      background 110ms ease !important;
  position:        relative !important;
}

.chkApp .sapMSegBBtn:last-child,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn:last-child {
  border-right: 0 !important;
}

body.chkAppRoot.appLight .chkApp .sapMSegBBtn {
  border-right-color: rgba(118, 162, 218, 0.36) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSegBBtn {
  border-right-color: rgba(77, 177, 255, 0.12) !important;
}

/* ── Inner label ── */
.chkApp .sapMSegBBtnInner,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn .sapMSegBBtnInner {
  display:         flex !important;
  align-items:     center !important;
  justify-content: center !important;
  gap:             0.24rem !important;
  width:           100% !important;
  border:          0 !important;
  border-radius:   0 !important;  /* container clips */
  background:      transparent !important;
  box-shadow:      none !important;
  padding:         0 0.82rem !important;
  min-height:      1.88rem !important;
  font-size:       0.79rem !important;
  font-weight:     600 !important;
  letter-spacing:  0.006em !important;
  white-space:     nowrap !important;
  line-height:     1 !important;
  transition:      color 110ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMSegBBtnInner {
  color: rgba(44, 68, 108, 0.76) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSegBBtnInner {
  color: rgba(var(--hz-accent-rgb, 77,177,255), 0.58) !important;
}

/* ── Hover unselected ── */
.chkApp .sapMSegBBtn:not(.sapMSegBBtnSel):hover {
  background: var(--hz-accent-tint, rgba(0,112,242,0.07)) !important;
}

.chkApp .sapMSegBBtn:not(.sapMSegBBtnSel):hover .sapMSegBBtnInner {
  color: var(--hz-accent, var(--accent)) !important;
}

/* ── SELECTED states ── */

/* All (1st child) — accent blue */
.chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(1),
.chkApp .sapMSegBBtn.sapMSegBBtnSel:not(:nth-child(2)):not(:nth-child(3)) {
  background: var(--hz-accent, #0070F2) !important;
  border-right-color: rgba(255,255,255,0.18) !important;
}

/* Failed (2nd child) — Horizon danger */
.chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(2) {
  background: var(--hz-danger, #CC0000) !important;
  border-right-color: rgba(255,255,255,0.16) !important;
}

/* Success (3rd child) — Horizon success */
.chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(3) {
  background: var(--hz-success, #1A7C40) !important;
  border-right-color: rgba(255,255,255,0.16) !important;
}

/* Label on any selected */
.chkApp .sapMSegBBtn.sapMSegBBtnSel .sapMSegBBtnInner,
.chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel .sapMSegBBtnInner {
  color:       rgba(255, 255, 255, 0.97) !important;
  font-weight: 700 !important;
  text-shadow: 0 1px 3px rgba(0,0,0,0.18) !important;
  box-shadow:  none !important;
}

/* Dark overrides for danger/success — lighter hue readable on dark track */
body.chkAppRoot.appDark .chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(2) {
  background: var(--hz-danger, #FF5C77) !important;
}

body.chkAppRoot.appDark .chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(3) {
  background: var(--hz-success, #5DC122) !important;
}

body.chkAppRoot.appDark .chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(2) .sapMSegBBtnInner,
body.chkAppRoot.appDark .chkApp .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(3) .sapMSegBBtnInner {
  color: rgba(0, 0, 0, 0.88) !important;
  text-shadow: none !important;
}

/* Disabled */
.chkApp .sapMSegBBtn.sapMSegBBtnDis,
.chkApp .sapMSegBBtn[aria-disabled="true"] {
  opacity:        0.36 !important;
  cursor:         not-allowed !important;
  pointer-events: none !important;
}

/* Kill old radius from first/last inner rules */
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn:first-child .sapMSegBBtnInner,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn:last-child .sapMSegBBtnInner {
  border-radius: 0 !important;
}

/* Kill box-shadows from old nth-child rules */
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:first-child .sapMSegBBtnInner,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:nth-child(2) .sapMSegBBtnInner,
.chkApp .searchFilterExperienceShell .resultSegmentControl .sapMSegBBtn.sapMSegBBtnSel:last-child .sapMSegBBtnInner {
  background:  transparent !important;
  box-shadow:  none !important;
  border-radius: 0 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 3 · BUTTONS — 6 MICRO-STATES PER SEMANTIC VARIANT
   idle → hover → active → focus → loading → disabled
   ══════════════════════════════════════════════════════════════ */

/* ── Universal layout ── */
.chkApp .sapMBtn .sapMBtnInner {
  display:         inline-flex !important;
  align-items:     center !important;
  justify-content: center !important;
  gap:             0.3rem !important;
  border-radius:   999px !important;
  font-size:       0.8rem !important;
  font-weight:     620 !important;
  letter-spacing:  0.01em !important;
  white-space:     nowrap !important;
  border-width:    1.5px !important;
  border-style:    solid !important;
  overflow:        hidden !important;
  position:        relative !important;
  transition:
    transform    110ms cubic-bezier(0.22,0.61,0.36,1),
    box-shadow   160ms ease,
    border-color 130ms ease,
    background   120ms ease,
    color        120ms ease,
    filter       130ms ease !important;
}

/* Icon perfect alignment */
.chkApp .sapMBtn .sapMBtnInner .sapUiIcon,
.chkApp .sapMBtn .sapMBtnInner .sapMBtnIconLeft,
.chkApp .sapMBtn .sapMBtnInner .sapMBtnIconRight {
  font-size:    1em !important;
  line-height:  1 !important;
  display:      inline-flex !important;
  align-items:  center !important;
  flex-shrink:  0 !important;
  position:     static !important;
  top:          auto !important;
  margin:       0 !important;
}

.chkApp .sapMBtn .sapMBtnContent {
  display:     inline-flex !important;
  align-items: center !important;
  line-height: 1.1 !important;
}

/* Icon-only: square */
.chkApp .sapMBtn.sapMBtnIconOnly .sapMBtnInner {
  min-width:    2rem !important;
  width:        2rem !important;
  height:       2rem !important;
  padding:      0 !important;
  aspect-ratio: 1 !important;
}

/* ──────── STATE 1: IDLE ──────── */

/* Default */
body.chkAppRoot.appLight .chkApp .sapMBtnDefault .sapMBtnInner {
  background:   rgba(255, 255, 255, 0.94) !important;
  border-color: rgba(118, 162, 218, 0.55) !important;
  color:        rgba(24, 44, 80, 0.90) !important;
  box-shadow:   0 1px 2px rgba(12,28,52,0.06),
                inset 0 1px 0 rgba(255,255,255,0.80) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtnDefault .sapMBtnInner {
  background:   rgba(22, 38, 66, 0.92) !important;
  border-color: rgba(77, 177, 255, 0.18) !important;
  color:        rgba(208, 226, 252, 0.90) !important;
  box-shadow:   0 1px 2px rgba(0,2,12,0.22),
                inset 0 1px 0 rgba(200,224,255,0.06) !important;
}

/* Emphasized — solid Horizon accent */
body.chkAppRoot.appLight .chkApp .sapMBtnEmphasized .sapMBtnInner {
  background:   var(--hz-accent, #0070F2) !important;
  border-color: rgba(0, 80, 200, 0.55) !important;
  color:        rgba(255, 255, 255, 0.98) !important;
  box-shadow:   0 2px 8px rgba(0,112,242,0.26),
                inset 0 1px 0 rgba(255,255,255,0.22) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtnEmphasized .sapMBtnInner {
  background:   var(--hz-accent, #4DB1FF) !important;
  border-color: rgba(55, 155, 240, 0.50) !important;
  color:        rgba(0, 16, 40, 0.97) !important;
  box-shadow:   0 2px 8px rgba(77,177,255,0.28),
                inset 0 1px 0 rgba(255,255,255,0.24) !important;
}

/* Ghost */
.chkApp .sapMBtnTransparent .sapMBtnInner {
  background:   transparent !important;
  border-color: transparent !important;
  color:        var(--hz-accent, var(--accent)) !important;
  box-shadow:   none !important;
}

/* Negative */
body.chkAppRoot.appLight .chkApp .sapMBtnNegative .sapMBtnInner {
  background:   var(--hz-danger, #CC0000) !important;
  border-color: rgba(170,0,0,0.52) !important;
  color:        rgba(255,255,255,0.98) !important;
  box-shadow:   0 2px 8px rgba(204,0,0,0.22),
                inset 0 1px 0 rgba(255,255,255,0.18) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtnNegative .sapMBtnInner {
  background:   var(--hz-danger, #FF5C77) !important;
  border-color: rgba(220,50,80,0.50) !important;
  color:        rgba(0,0,0,0.92) !important;
  box-shadow:   0 2px 8px rgba(255,92,119,0.26) !important;
}

/* Success */
body.chkAppRoot.appLight .chkApp .sapMBtnSuccess .sapMBtnInner,
body.chkAppRoot.appLight .chkApp .btnSuccess .sapMBtnInner {
  background:   var(--hz-success, #1A7C40) !important;
  border-color: rgba(14,100,48,0.52) !important;
  color:        rgba(255,255,255,0.98) !important;
  box-shadow:   0 2px 8px rgba(26,124,64,0.22),
                inset 0 1px 0 rgba(255,255,255,0.18) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtnSuccess .sapMBtnInner,
body.chkAppRoot.appDark .chkApp .btnSuccess .sapMBtnInner {
  background:   var(--hz-success, #5DC122) !important;
  border-color: rgba(65,180,24,0.50) !important;
  color:        rgba(0,0,0,0.90) !important;
  box-shadow:   0 2px 8px rgba(93,193,34,0.24) !important;
}

/* ──────── STATE 2: HOVER ──────── */

body.chkAppRoot.appLight .chkApp .sapMBtnDefault:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-1.5px) !important;
  border-color: rgba(0,112,242,0.40) !important;
  color:        var(--hz-accent, #0070F2) !important;
  box-shadow:   0 4px 12px rgba(0,112,242,0.10),
                inset 0 1px 0 rgba(255,255,255,0.80) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtnDefault:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-1.5px) !important;
  border-color: rgba(77,177,255,0.34) !important;
  color:        var(--hz-accent, #4DB1FF) !important;
  box-shadow:   0 4px 12px rgba(77,177,255,0.12),
                inset 0 1px 0 rgba(200,224,255,0.07) !important;
}

.chkApp .sapMBtnEmphasized:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-2px) !important;
  filter:       brightness(1.09) saturate(1.05) !important;
  box-shadow:   0 6px 20px rgba(var(--hz-accent-rgb, 0,112,242), 0.36),
                inset 0 1px 0 rgba(255,255,255,0.26) !important;
}

.chkApp .sapMBtnTransparent:not(.sapMBtnDisabled):hover .sapMBtnInner {
  background:   var(--hz-accent-tint, rgba(0,112,242,0.08)) !important;
  border-color: var(--hz-accent-border, rgba(0,112,242,0.26)) !important;
  transform:    translateY(-1px) !important;
}

.chkApp .sapMBtnNegative:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-2px) !important;
  filter:       brightness(1.08) !important;
  box-shadow:   0 6px 18px rgba(var(--hz-danger-rgb, 204,0,0), 0.28),
                inset 0 1px 0 rgba(255,255,255,0.18) !important;
}

.chkApp .sapMBtnSuccess:not(.sapMBtnDisabled):hover .sapMBtnInner,
.chkApp .btnSuccess:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-2px) !important;
  filter:       brightness(1.08) !important;
  box-shadow:   0 6px 18px rgba(var(--hz-success-rgb, 26,124,64), 0.28),
                inset 0 1px 0 rgba(255,255,255,0.18) !important;
}

/* ──────── STATE 3: ACTIVE / PRESS ──────── */

.chkApp .sapMBtn:not(.sapMBtnDisabled):active .sapMBtnInner {
  transform:           scale(0.956) !important;
  filter:              brightness(0.92) !important;
  box-shadow:          inset 0 2px 4px rgba(0,0,0,0.14) !important;
  transition-duration: 45ms !important;
}

/* ──────── STATE 4: FOCUS ──────── */

.chkApp .sapMBtn:focus-visible .sapMBtnInner {
  outline:    none !important;
  box-shadow:
    0 0 0 2px rgba(255,255,255,0.95),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 0,112,242), 0.64) !important;
}

.chkApp .sapMBtnNegative:focus-visible .sapMBtnInner {
  box-shadow:
    0 0 0 2px rgba(255,255,255,0.95),
    0 0 0 4.5px rgba(var(--hz-danger-rgb, 204,0,0), 0.56) !important;
}

body.chkAppRoot.appDark .chkApp .sapMBtn:focus-visible .sapMBtnInner {
  box-shadow:
    0 0 0 2px rgba(8,18,38,0.96),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 77,177,255), 0.66) !important;
}

/* ──────── STATE 5: LOADING / BUSY ──────── */

@keyframes _btnSweep {
  0%   { transform: translateX(-120%); }
  100% { transform: translateX(220%); }
}

.chkApp .sapMBtnBusy .sapMBtnInner {
  opacity:        0.70 !important;
  cursor:         wait !important;
  pointer-events: none !important;
}

.chkApp .sapMBtnBusy .sapMBtnInner::before {
  content:      '';
  position:     absolute;
  inset-block:  0;
  width:        38%;
  background:   linear-gradient(
    90deg, transparent, rgba(255,255,255,0.30), transparent
  );
  animation:    _btnSweep 1.1s ease-in-out infinite;
  pointer-events: none;
}

/* ──────── STATE 6: DISABLED ──────── */

.chkApp .sapMBtnDisabled .sapMBtnInner {
  opacity:        0.33 !important;
  cursor:         not-allowed !important;
  pointer-events: none !important;
  transform:      none !important;
  filter:         none !important;
  box-shadow:     none !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 4 · SWITCH — per-theme accent
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMSwt {
  display:         inline-flex !important;
  align-items:     center !important;
  border-radius:   999px !important;
  border:          1.5px solid !important;
  min-height:      1.60rem !important;
  min-width:       2.80rem !important;
  padding:         2px !important;
  cursor:          pointer !important;
  transition:      background 200ms ease, border-color 200ms ease !important;
}

/* OFF */
body.chkAppRoot.appLight .chkApp .sapMSwt:not(.sapMSwtOn) {
  background:   var(--hz-sw-off-bg, rgba(218,230,248,0.82)) !important;
  border-color: var(--hz-sw-off-border, rgba(120,162,216,0.52)) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSwt:not(.sapMSwtOn) {
  background:   var(--hz-sw-off-bg, rgba(16,28,50,0.88)) !important;
  border-color: var(--hz-sw-off-border, rgba(77,177,255,0.18)) !important;
}

/* ON */
.chkApp .sapMSwt.sapMSwtOn {
  background:   var(--hz-sw-on-bg, var(--hz-accent)) !important;
  border-color: rgba(var(--hz-sw-on-rgb, var(--accent-rgb)), 0.44) !important;
  box-shadow:   0 2px 8px rgba(var(--hz-sw-on-rgb, var(--accent-rgb)), 0.26) !important;
}

/* Thumb */
.chkApp .sapMSwtHandle {
  border-radius: 999px !important;
  background:    linear-gradient(180deg, #fff 0%, rgba(238,246,255,0.95) 100%) !important;
  box-shadow:    0 1px 4px rgba(4,12,26,0.18),
                 inset 0 1px 0 rgba(255,255,255,0.90) !important;
  transition:    transform 240ms cubic-bezier(0.22,0.61,0.36,1) !important;
}

/* Hover ring */
.chkApp .sapMSwt:not(.sapMSwtDisabled):hover {
  box-shadow: 0 0 0 3px rgba(var(--hz-sw-on-rgb, var(--accent-rgb)), 0.13) !important;
}

/* Labels */
.chkApp .sapMSwtText {
  font-size:      0.64rem !important;
  font-weight:    700 !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
  line-height:    1 !important;
}

body.chkAppRoot.appLight .chkApp .sapMSwt:not(.sapMSwtOn) .sapMSwtText {
  color: rgba(80,110,158,0.60) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSwt:not(.sapMSwtOn) .sapMSwtText {
  color: rgba(var(--hz-accent-rgb, 77,177,255), 0.40) !important;
}

.chkApp .sapMSwt.sapMSwtOn .sapMSwtText {
  color: rgba(255, 255, 255, 0.92) !important;
}

.chkApp .sapMSwt.sapMSwtDisabled {
  opacity:        0.35 !important;
  cursor:         not-allowed !important;
  pointer-events: none !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 5 · INPUTS — transparent blend + 7-state machine
   ══════════════════════════════════════════════════════════════ */

/* ── Base: transparent, minimal border ── */
.chkApp .sapMInputBaseContentWrapper {
  background:    var(--hz-in-bg, rgba(255,255,255,0.44)) !important;
  border:        1.5px solid var(--hz-in-border, rgba(118,162,218,0.50)) !important;
  border-radius: 0.5rem !important;
  box-shadow:    none !important;
  transition:
    border-color 130ms ease,
    background   130ms ease,
    box-shadow   130ms ease !important;
}

/* ── Hover ── */
.chkApp .sapMInputBaseContentWrapper:hover {
  background:   var(--hz-in-bg-hover, rgba(255,255,255,0.70)) !important;
  border-color: var(--hz-accent-border, rgba(0,112,242,0.28)) !important;
}

/* ── Focus ── */
.chkApp .sapMInputBaseContentWrapper:focus-within {
  background:   var(--hz-in-bg-focus, rgba(255,255,255,0.90)) !important;
  border-color: var(--hz-accent, var(--accent)) !important;
  box-shadow:   0 0 0 3px var(--hz-in-ring, rgba(0,112,242,0.16)) !important;
}

/* ── Error ── */
.chkApp .sapMInputBaseError .sapMInputBaseContentWrapper,
.chkApp .sapMInputBase.sapMInputBaseError .sapMInputBaseContentWrapper {
  border-color: var(--hz-danger, #CC0000) !important;
  background:   var(--hz-danger-tint, rgba(204,0,0,0.05)) !important;
}

.chkApp .sapMInputBaseError .sapMInputBaseContentWrapper:focus-within {
  box-shadow: 0 0 0 3px rgba(var(--hz-danger-rgb, 204,0,0), 0.14) !important;
}

/* ── Success ── */
.chkApp .sapMInputBaseSuccess .sapMInputBaseContentWrapper,
.chkApp .sapMInputBase.sapMInputBaseSuccess .sapMInputBaseContentWrapper {
  border-color: var(--hz-success, #1A7C40) !important;
  background:   var(--hz-success-tint, rgba(26,124,64,0.05)) !important;
}

.chkApp .sapMInputBaseSuccess .sapMInputBaseContentWrapper:focus-within {
  box-shadow: 0 0 0 3px rgba(var(--hz-success-rgb, 26,124,64), 0.14) !important;
}

/* ── Warning ── */
.chkApp .sapMInputBaseWarning .sapMInputBaseContentWrapper,
.chkApp .sapMInputBase.sapMInputBaseWarning .sapMInputBaseContentWrapper {
  border-color: var(--hz-warning, #C35500) !important;
  background:   var(--hz-warning-tint, rgba(195,85,0,0.05)) !important;
}

/* ── Read-only ── */
.chkApp .sapMInputBaseReadonly .sapMInputBaseContentWrapper {
  background:   transparent !important;
  border-color: var(--hz-accent-border, rgba(0,112,242,0.18)) !important;
  border-style: dashed !important;
  cursor:       default !important;
}

/* ── Disabled ── */
.chkApp .sapMInputBaseDisabled .sapMInputBaseContentWrapper {
  opacity:      0.40 !important;
  cursor:       not-allowed !important;
  background:   rgba(0,0,0,0.025) !important;
  border-style: dashed !important;
}

/* Inner transparent */
.chkApp .sapMInputBaseInner {
  background:  transparent !important;
  color:       var(--text-main) !important;
}

/* Placeholder */
body.chkAppRoot.appLight .chkApp .sapMInputBase input::placeholder,
body.chkAppRoot.appLight .chkApp .sapMInputBase textarea::placeholder {
  color:   rgba(88, 124, 178, 0.60) !important;
  opacity: 1 !important;
}

body.chkAppRoot.appDark .chkApp .sapMInputBase input::placeholder,
body.chkAppRoot.appDark .chkApp .sapMInputBase textarea::placeholder {
  color:   rgba(var(--hz-accent-rgb, 77,177,255), 0.34) !important;
  opacity: 1 !important;
}

/* ── Select / Combo ── */
.chkApp .sapMSlt {
  background:    var(--hz-in-bg) !important;
  border:        1.5px solid var(--hz-in-border) !important;
  border-radius: 0.5rem !important;
  box-shadow:    none !important;
  transition:    border-color 130ms ease, background 130ms ease !important;
}

.chkApp .sapMSlt:hover { background: var(--hz-in-bg-hover) !important; }

.chkApp .sapMSlt:focus,
.chkApp .sapMSlt.sapMSltFocused {
  border-color: var(--hz-accent, var(--accent)) !important;
  background:   var(--hz-in-bg-focus) !important;
  box-shadow:   0 0 0 3px var(--hz-in-ring) !important;
}

/* ── Search field pill ── */
.chkApp .sapMSFF {
  background:    var(--hz-in-bg) !important;
  border:        1.5px solid var(--hz-in-border) !important;
  border-radius: 999px !important;
  box-shadow:    none !important;
  transition:    border-color 130ms ease, background 130ms ease !important;
}

.chkApp .sapMSFF:focus-within {
  background:   var(--hz-in-bg-focus) !important;
  border-color: var(--hz-accent, var(--accent)) !important;
  box-shadow:   0 0 0 3px var(--hz-in-ring) !important;
}

/* ── Textarea ── */
.chkApp .sapMTextArea .sapMInputBaseContentWrapper {
  border-radius: 0.625rem !important;
  min-height:    3.5rem !important;
  resize:        vertical !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 6 · FOCUS RINGS — per-theme, WCAG AA
   ══════════════════════════════════════════════════════════════ */

.chkApp :focus                          { outline: none !important; }
.chkApp :focus:not(:focus-visible)      { box-shadow: none !important; }

.chkApp :focus-visible {
  outline:       none !important;
  border-radius: inherit !important;
  box-shadow:
    0 0 0 2px rgba(255,255,255,0.96),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 0,112,242), 0.64) !important;
}

body.chkAppRoot.appDark .chkApp :focus-visible {
  box-shadow:
    0 0 0 2px rgba(6,14,28,0.96),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 77,177,255), 0.66) !important;
}

/* Selection */
.chkApp ::selection {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.18) !important;
  color:      inherit !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 7 · OBJECT STATUS + MESSAGE STRIP — semantic colours
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMObjStatusStatePositive    .sapMObjStatusText { color: var(--hz-success, #1A7C40) !important; }
.chkApp .sapMObjStatusStateNegative    .sapMObjStatusText { color: var(--hz-danger,  #CC0000) !important; }
.chkApp .sapMObjStatusStateCritical    .sapMObjStatusText { color: var(--hz-warning, #C35500) !important; }
.chkApp .sapMObjStatusStateInformation .sapMObjStatusText { color: var(--hz-accent,  var(--accent)) !important; }

.chkApp .sapMObjStatusStatePositive    .sapUiIcon { color: var(--hz-success) !important; }
.chkApp .sapMObjStatusStateNegative    .sapUiIcon { color: var(--hz-danger)  !important; }
.chkApp .sapMObjStatusStateCritical    .sapUiIcon { color: var(--hz-warning) !important; }
.chkApp .sapMObjStatusStateInformation .sapUiIcon { color: var(--hz-accent)  !important; }

.chkApp .sapMMsgStripError,   .chkApp .sapMMessageStripError {
  background: var(--hz-danger-tint)  !important;
  border-color: var(--hz-danger-border) !important;
  color: var(--hz-danger, #CC0000) !important;
}

.chkApp .sapMMsgStripWarning, .chkApp .sapMMessageStripWarning {
  background: var(--hz-warning-tint)  !important;
  border-color: var(--hz-warning-border) !important;
  color: var(--hz-warning, #C35500) !important;
}

.chkApp .sapMMsgStripSuccess, .chkApp .sapMMessageStripSuccess {
  background: var(--hz-success-tint)  !important;
  border-color: var(--hz-success-border) !important;
  color: var(--hz-success, #1A7C40) !important;
}

.chkApp .sapMMsgStripInformation, .chkApp .sapMMessageStripInformation {
  background: var(--hz-accent-tint)   !important;
  border-color: var(--hz-accent-border) !important;
  color: var(--hz-accent, var(--accent)) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 8 · NEW COMPONENTS
   ══════════════════════════════════════════════════════════════ */

/* ── Breadcrumb ── */
.chkApp .sapMBreadcrumbs,
.chkApp .sapMBreadcrumb {
  display:     inline-flex !important;
  align-items: center !important;
  flex-wrap:   wrap !important;
  gap:         0.12rem !important;
  font-size:   0.79rem !important;
  font-weight: 500 !important;
}

.chkApp .sapMBreadcrumbsCurrentLocation { font-weight: 700 !important; }

.chkApp .sapMBreadcrumbsLink {
  color:           var(--hz-accent, var(--accent)) !important;
  text-decoration: none !important;
  border-radius:   0.3rem !important;
  padding:         0.06rem 0.18rem !important;
  transition:      background 110ms ease !important;
}

.chkApp .sapMBreadcrumbsLink:hover {
  background: var(--hz-accent-tint) !important;
}

.chkApp .sapMBreadcrumbsSeparator {
  color:   var(--text-muted, #888) !important;
  opacity: 0.50 !important;
  font-size: 0.74rem !important;
}

/* ── Tooltip ── */
.sapUiTooltip,
[role="tooltip"],
.sapUiRespRectangle {
  border-radius: 0.5rem !important;
  font-size:     0.78rem !important;
  font-weight:   500 !important;
  line-height:   1.45 !important;
  padding:       0.35rem 0.60rem !important;
  max-width:     22rem !important;
  pointer-events:none !important;
  animation:     _tooltipIn 140ms ease both !important;
}

@keyframes _tooltipIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

body.chkAppRoot.appLight .sapUiTooltip {
  background:   rgba(24, 40, 72, 0.96) !important;
  color:        rgba(220, 232, 252, 0.97) !important;
  border:       1px solid rgba(0, 112, 242, 0.18) !important;
  box-shadow:   0 4px 14px rgba(0, 2, 14, 0.22) !important;
}

body.chkAppRoot.appDark .sapUiTooltip {
  background:   rgba(8, 16, 34, 0.97) !important;
  color:        rgba(200, 220, 252, 0.97) !important;
  border:       1px solid rgba(77, 177, 255, 0.18) !important;
  box-shadow:   0 4px 14px rgba(0, 2, 14, 0.38) !important;
}

/* ── Pagination ── */
.chkApp .sapMPagingButton {
  display:     inline-flex !important;
  align-items: center !important;
  gap:         0.2rem !important;
}

.chkApp .sapMPagingButton .sapMBtn .sapMBtnInner {
  min-width:    2rem !important;
  height:       2rem !important;
  padding:      0 0.5rem !important;
  border-radius:0.42rem !important;
  font-size:    0.79rem !important;
  font-weight:  600 !important;
}

.chkApp .sapMPagingButton .sapMBtn[aria-current="true"] .sapMBtnInner,
.chkApp .sapMPagingButton .sapMBtn.sapMBtnActive .sapMBtnInner {
  background:   var(--hz-accent, var(--accent)) !important;
  border-color: var(--hz-accent-border) !important;
  color:        rgba(255,255,255,0.97) !important;
}

/* ── Object Header ── */
.chkApp .sapMObjectHeaderTitleText,
.chkApp .sapMObjectHeader-title {
  font-size:      1.05rem !important;
  font-weight:    750 !important;
  letter-spacing: -0.016em !important;
  line-height:    1.25 !important;
}

.chkApp .sapMObjectNumberStatePositive .sapMObjectNumberText {
  color: var(--hz-success, #1A7C40) !important;
}

.chkApp .sapMObjectNumberStateNegative .sapMObjectNumberText {
  color: var(--hz-danger,  #CC0000) !important;
}

.chkApp .sapMObjectNumberStateCritical .sapMObjectNumberText {
  color: var(--hz-warning, #C35500) !important;
}

/* ── ComboBox list items ── */
.sapMComboBoxList .sapMLIB {
  border-radius: 0.4rem !important;
  margin:        2px 4px !important;
  min-height:    2.05rem !important;
  font-size:     0.84rem !important;
  font-weight:   500 !important;
  transition:    background 90ms ease !important;
}

.sapMComboBoxList .sapMLIBHov {
  background: var(--hz-accent-tint, rgba(0,112,242,0.07)) !important;
}

.sapMComboBoxList .sapMLIBSelected {
  background:  rgba(var(--hz-accent-rgb, 0,112,242), 0.12) !important;
  font-weight: 650 !important;
}

.sapMComboBoxList .sapMSelectListItemHighlightText {
  color:       var(--hz-accent, var(--accent)) !important;
  font-weight: 700 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 9 · TABLE COLUMN HEADER POLISH
   ══════════════════════════════════════════════════════════════ */

/* Header text — all-caps micro labels */
.chkApp .searchResultsTable .sapMListTblHeaderCell .sapMText,
.chkApp .detailSectionCard  .sapMListTblHeaderCell .sapMText {
  font-size:      0.65rem !important;
  font-weight:    800 !important;
  letter-spacing: 0.09em !important;
  text-transform: uppercase !important;
}

/* Hover column */
.chkApp .searchResultsTable .sapMListTblHeaderCell:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
  cursor:     pointer !important;
}

/* Sort icon */
.chkApp .sapMListTblHeaderCell .sapUiIcon {
  color:     var(--hz-accent, var(--accent)) !important;
  opacity:   0.65 !important;
  font-size: 0.72rem !important;
}

/* Selected row accent bar */
.chkApp .searchResultsTable .sapMLIBSelected .sapMListTblCell:first-child {
  border-inline-start: 3px solid var(--hz-accent, var(--accent)) !important;
}

/* Column resize handle */
.chkApp .sapMColumnHeaderResizer {
  width:      2px !important;
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.22) !important;
  border-radius: 1px !important;
  opacity:    0 !important;
  transition: opacity 130ms ease !important;
}

.chkApp .sapMListTblHeaderCell:hover .sapMColumnHeaderResizer {
  opacity: 1 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 10 · CARD HOVER GLOW — per-theme
   ══════════════════════════════════════════════════════════════ */

body.chkAppRoot.appLight .chkApp .kpiCard:hover,
body.chkAppRoot.appLight .chkApp .searchAnalyticsCard:hover,
body.chkAppRoot.appLight .chkApp .workflowStageCard:hover {
  transform:    translateY(-2px) !important;
  border-color: rgba(0, 112, 242, 0.24) !important;
  box-shadow:   0 4px 18px rgba(0, 112, 242, 0.12),
                0 1px 4px rgba(12,28,52,0.06) !important;
}

body.chkAppRoot.appDark .chkApp .kpiCard:hover,
body.chkAppRoot.appDark .chkApp .searchAnalyticsCard:hover,
body.chkAppRoot.appDark .chkApp .workflowStageCard:hover {
  transform:    translateY(-2px) !important;
  border-color: rgba(77, 177, 255, 0.26) !important;
  box-shadow:   0 6px 22px rgba(77, 177, 255, 0.17),
                0 2px 6px rgba(0,2,14,0.30) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 11 · SHELL — accent sweep line
   ══════════════════════════════════════════════════════════════ */

.chkApp .appShellHeader::before {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(var(--hz-accent-rgb, 0,112,242), 0.50) 35%,
    rgba(var(--hz-accent-rgb, 0,112,242), 0.22) 65%,
    transparent 100%
  ) !important;
}

.chkApp .shellActionBtn:not(.sapMBtnDisabled):hover .sapMBtnInner,
.chkApp .shellUserBtn:not(.sapMBtnDisabled):hover .sapMBtnInner {
  border-color: rgba(var(--hz-accent-rgb, 0,112,242), 0.38) !important;
  color:        var(--hz-accent, var(--accent)) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 12 · SCROLLBAR — thin, per-theme accent
   ══════════════════════════════════════════════════════════════ */

.chkApp *,
.sapMPopover *,
.sapMDialog *,
.sapMSelectList * {
  scrollbar-width: thin;
  scrollbar-color: rgba(var(--hz-accent-rgb, 0,112,242), 0.20) transparent;
}

.chkApp *::-webkit-scrollbar         { width: 3px; height: 3px; }
.chkApp *::-webkit-scrollbar-track   { background: transparent; }
.chkApp *::-webkit-scrollbar-corner  { background: transparent; }
.chkApp *::-webkit-scrollbar-thumb   {
  border-radius: 999px;
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.20);
}
.chkApp *::-webkit-scrollbar-thumb:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.45);
}

/* ══════════════════════════════════════════════════════════════
   CH 13 · LINKS
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMLnk {
  color:           var(--hz-accent, var(--accent)) !important;
  text-decoration: none !important;
  border-bottom:   1px solid rgba(var(--hz-accent-rgb, 0,112,242), 0.26) !important;
  font-weight:     500 !important;
  transition:      border-color 120ms ease, opacity 120ms ease !important;
}

.chkApp .sapMLnk:hover {
  border-bottom-color: rgba(var(--hz-accent-rgb, 0,112,242), 0.70) !important;
}

.chkApp .sapMLnk:active { opacity: 0.66 !important; }

/* ══════════════════════════════════════════════════════════════
   CH 14 · HIGH CONTRAST · REDUCED MOTION · PRINT
   ══════════════════════════════════════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  .chkApp *, .chkApp *::before, .chkApp *::after,
  .sapMDialog, .sapMPopover, .sapMSelectList, .sapMMessageToast {
    animation-duration:  1ms !important;
    transition-duration: 1ms !important;
  }
  .chkApp .sapMBtnBusy .sapMBtnInner::before   { animation: none !important; }
  .chkApp .sapMBtn:not(.sapMBtnDisabled):hover .sapMBtnInner,
  .chkApp .kpiCard:hover, .chkApp .searchAnalyticsCard:hover {
    transform: none !important;
    filter:    none !important;
  }
}

@media (forced-colors: active) {
  .chkApp .sapMSegBBtn.sapMSegBBtnSel  { forced-color-adjust: none; background: Highlight !important; }
  .chkApp .sapMSegBBtn.sapMSegBBtnSel .sapMSegBBtnInner { color: HighlightText !important; }
  .chkApp .sapMSegB    { border: 2px solid ButtonText !important; }
  .chkApp .sapMBtnEmphasized .sapMBtnInner { forced-color-adjust: none; background: Highlight !important; color: HighlightText !important; border-color: Highlight !important; }
  .chkApp .sapMSwt.sapMSwtOn { forced-color-adjust: none; background: Highlight !important; border-color: Highlight !important; }
  .chkApp .sapMInputBaseContentWrapper { border-color: ButtonText !important; background: Field !important; }
  .chkApp .sapMInputBaseContentWrapper:focus-within { outline: 2px solid Highlight !important; box-shadow: none !important; }
}

@media print {
  .chkApp .sapMSegB                  { border: 1px solid #333 !important; overflow: hidden !important; background: #fff !important; }
  .chkApp .sapMSegBBtn.sapMSegBBtnSel { background: #ddd !important; }
  .chkApp .sapMBtnEmphasized .sapMBtnInner { background: #eee !important; color: #000 !important; border-color: #333 !important; box-shadow: none !important; }
  .chkApp .sapMInputBaseContentWrapper { background: #fff !important; border-color: #ccc !important; }
  .chkApp .sapMSwt { border: 1px solid #333 !important; background: #fff !important; }
  .chkApp * { box-shadow: none !important; }
}

/* ================================================================
   9B_motion.css — Motion · Pictograms · Busy Indicators
   ================================================================
   Loads after 9A → highest specificity in chain.

   Ch 1   Busy Indicator system — 4 variants (dots/ring/bar/pulse)
   Ch 2   Local busy overlay — blurred card placeholder
   Ch 3   Page-level busy — full screen with branded animation
   Ch 4   Skeleton screens — staggered reveal
   Ch 5   Card / list item entry animations (stagger)
   Ch 6   Micro-interactions — button press ripple, input glow
   Ch 7   Status icon pictograms — per semantic + animated badge
   Ch 8   KPI number counter animation
   Ch 9   Toast / Notification entrance choreography
   Ch 10  Dialog / Popover spring entrance
   Ch 11  Tab bar indicator slide
   Ch 12  Page transition system
   Ch 13  Data update flash
   Ch 14  Reduced motion safe-guard
   ================================================================ */

/* ══════════════════════════════════════════════════════════════
   CH 1 · BUSY INDICATOR — 4 visual variants
   ══════════════════════════════════════════════════════════════ */

/* ── Shared container ── */
.chkApp .sapMBusyIndicator {
  display:         inline-flex !important;
  align-items:     center !important;
  justify-content: center !important;
  gap:             0 !important;
  position:        relative !important;
}

/* ══ VARIANT A: 3-dot bounce (default) ══ */

.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot {
  display:       block !important;
  width:         0.44rem !important;
  height:        0.44rem !important;
  margin:        0 0.16rem !important;
  border-radius: 50% !important;
  background:    var(--hz-accent, var(--accent)) !important;
  box-shadow:    0 0 0 0 rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.0) !important;
  animation:     _busyBounce 1.2s cubic-bezier(0.36, 0.07, 0.19, 0.97) infinite !important;
  will-change:   transform, opacity !important;
}

.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(1) { animation-delay: 0s !important; }
.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(2) { animation-delay: 0.16s !important; }
.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(3) { animation-delay: 0.32s !important; }

@keyframes _busyBounce {
  0%, 60%, 100% {
    opacity:   0.22;
    transform: translateY(0) scale(0.72);
  }
  30% {
    opacity:   1;
    transform: translateY(-0.36rem) scale(1.15);
    box-shadow: 0 0.36rem 0.5rem rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.24);
  }
}

/* Dark theme: glow on dots */
body.chkAppRoot.appDark .chkApp .sapMBusyIndicator .sapMBusyIndicatorDot {
  background: var(--hz-accent, #4DB1FF) !important;
}

/* ══ VARIANT B: Spinning ring (large contexts) ══ */
/* Applied when parent has data-busy-style="ring" or .busyRing */

.chkApp .busyRing::before,
.chkApp [data-busy-style="ring"] .sapMBusyIndicator::before {
  content:       '';
  display:       block;
  width:         1.5rem;
  height:        1.5rem;
  border-radius: 50%;
  border:        2.5px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.18);
  border-top-color: var(--hz-accent, var(--accent));
  animation:     _busySpin 0.7s linear infinite;
  flex-shrink:   0;
}

@keyframes _busySpin {
  to { transform: rotate(360deg); }
}

/* ══ VARIANT C: Progress bar (horizontal content) ══ */

.chkApp .busyBar {
  width:         100%;
  height:        2px;
  background:    rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.12);
  border-radius: 999px;
  overflow:      hidden;
  position:      relative;
}

.chkApp .busyBar::after {
  content:       '';
  position:      absolute;
  inset-block:   0;
  width:         40%;
  background:    linear-gradient(
    90deg,
    transparent,
    var(--hz-accent, var(--accent)),
    transparent
  );
  border-radius: inherit;
  animation:     _busyBarSlide 1.4s ease-in-out infinite;
}

@keyframes _busyBarSlide {
  0%   { left: -40%; }
  100% { left: 140%; }
}

/* ══ VARIANT D: Pulse ring (overlay on table rows etc.) ══ */

.chkApp .busyPulse::after,
.chkApp .sapMListTblRow.sapMListTblBusy::after {
  content:       '';
  position:      absolute;
  inset:         0;
  border-radius: inherit;
  background:    rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.0);
  animation:     _busyRowPulse 1.8s ease-in-out infinite;
  pointer-events:none;
  z-index:       1;
}

@keyframes _busyRowPulse {
  0%,  100% { background: rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.0); }
  50%       { background: rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.05); }
}

/* ══ SAP BusyIndicator large — ring override ══ */

.chkApp .sapMBusyIndicator.sapMBusyIndicatorFull {
  width:  2.4rem !important;
  height: 2.4rem !important;
  position: relative !important;
}

.chkApp .sapMBusyIndicator.sapMBusyIndicatorFull::before {
  content:       '' !important;
  position:      absolute !important;
  inset:         0 !important;
  border-radius: 50% !important;
  border:        3px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.16) !important;
  border-top-color: var(--hz-accent, var(--accent)) !important;
  animation:     _busySpin 0.72s linear infinite !important;
}

.chkApp .sapMBusyIndicator.sapMBusyIndicatorFull .sapMBusyIndicatorDot {
  display: none !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 2 · LOCAL BUSY OVERLAY — blurred card placeholder
   ══════════════════════════════════════════════════════════════ */

/* SAP renders .sapUiLocalBusy on the component container */
.chkApp .sapUiLocalBusy {
  position:       relative !important;
  pointer-events: none !important;
}

/* Overlay */
.chkApp .sapUiLocalBusyIndicator {
  position:       absolute !important;
  inset:          0 !important;
  z-index:        100 !important;
  display:        flex !important;
  align-items:    center !important;
  justify-content:center !important;
  flex-direction: column !important;
  gap:            0.75rem !important;
  border-radius:  inherit !important;
  background:     rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.02) !important;
  animation:      _localBusyIn 220ms ease both !important;
}

body.chkAppRoot.appLight .chkApp .sapUiLocalBusyIndicator {
  background: rgba(248, 251, 255, 0.72) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiLocalBusyIndicator {
  background: rgba(14, 26, 48, 0.72) !important;
}

@keyframes _localBusyIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Dots inside local busy */
.chkApp .sapUiLocalBusyIndicator .sapMBusyIndicatorDot {
  width:  0.42rem !important;
  height: 0.42rem !important;
}

/* Optional text below dots */
.chkApp .sapUiLocalBusyIndicator .sapMBusyIndicatorText {
  font-size:      0.75rem !important;
  font-weight:    600 !important;
  letter-spacing: 0.04em !important;
  text-transform: uppercase !important;
  opacity:        0.55 !important;
  animation:      _busyTextBlink 2s ease-in-out infinite !important;
}

@keyframes _busyTextBlink {
  0%,  100% { opacity: 0.35; }
  50%        { opacity: 0.65; }
}

/* Shimmer wash on content behind overlay */
.chkApp .sapUiLocalBusy > *:not(.sapUiLocalBusyIndicator) {
  filter: blur(1.5px) !important;
  transition: filter 200ms ease !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 3 · BUSY DIALOG — full-page branded animation
   ══════════════════════════════════════════════════════════════ */

.chkApp .chkSkin .sapMDialog.sapMBusyDialog,
.sapMDialog.sapMBusyDialog {
  border-radius: 1.25rem !important;
  border:        1.5px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.18) !important;
  overflow:      hidden !important;
  animation:     _busyDialogIn 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

body.chkAppRoot.appLight .sapMDialog.sapMBusyDialog {
  background: rgba(255, 255, 255, 0.98) !important;
  box-shadow: 0 12px 40px rgba(12, 28, 52, 0.14), 0 2px 8px rgba(12,28,52,0.07) !important;
}

body.chkAppRoot.appDark .sapMDialog.sapMBusyDialog {
  background: rgba(17, 29, 52, 0.98) !important;
  box-shadow: 0 12px 40px rgba(0, 2, 14, 0.44), 0 2px 8px rgba(0,2,14,0.26) !important;
}

@keyframes _busyDialogIn {
  from { opacity: 0; transform: scale(0.88) translateY(8px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* Branded accent bar at top */
.chkApp .chkSkin .sapMDialog.sapMBusyDialog::before,
.sapMDialog.sapMBusyDialog::before {
  content:     '';
  display:     block;
  height:      2px;
  background:  linear-gradient(
    90deg,
    var(--hz-accent, var(--accent)) 0%,
    var(--hz-success, #1A7C40) 50%,
    var(--hz-accent, var(--accent)) 100%
  );
  background-size: 200% 100%;
  animation:   _busyAccentBar 2.4s linear infinite;
  flex-shrink: 0;
}

@keyframes _busyAccentBar {
  0%   { background-position: 0% 0%; }
  100% { background-position: 200% 0%; }
}

/* Large ring in busy dialog */
.sapMDialog.sapMBusyDialog .sapMBusyIndicator {
  width:  3rem !important;
  height: 3rem !important;
  position: relative !important;
  margin: 1rem auto !important;
}

.sapMDialog.sapMBusyDialog .sapMBusyIndicator::before {
  content:       '' !important;
  position:      absolute !important;
  inset:         0 !important;
  border-radius: 50% !important;
  border:        3.5px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.14) !important;
  border-top-color: var(--hz-accent, var(--accent)) !important;
  animation:     _busySpin 0.78s linear infinite !important;
}

.sapMDialog.sapMBusyDialog .sapMBusyIndicator::after {
  content:       '' !important;
  position:      absolute !important;
  inset:         5px !important;
  border-radius: 50% !important;
  border:        2px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.08) !important;
  border-bottom-color: rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.36) !important;
  animation:     _busySpin 1.3s linear infinite reverse !important;
}

.sapMDialog.sapMBusyDialog .sapMBusyIndicatorDot {
  display: none !important;
}

/* Dialog message text */
.sapMDialog.sapMBusyDialog .sapMBusyDialogLabel {
  font-size:      0.85rem !important;
  font-weight:    600 !important;
  letter-spacing: 0.01em !important;
  text-align:     center !important;
  opacity:        0.72 !important;
  animation:      _busyTextBlink 2.2s ease-in-out infinite !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 4 · SKELETON SCREENS — improved shimmer + stagger
   ══════════════════════════════════════════════════════════════ */

@keyframes _skelShimmer {
  0%   { background-position: -200% center; }
  100% { background-position:  200% center; }
}

@keyframes _skelFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.appSkeleton {
  border-radius:     0.5rem !important;
  background:
    linear-gradient(
      90deg,
      var(--appSkeletonBase, rgba(196,210,232,0.55)) 0%,
      var(--appSkeletonHighlight, rgba(255,255,255,0.70)) 50%,
      var(--appSkeletonBase, rgba(196,210,232,0.55)) 100%
    ) !important;
  background-size:   300% 100% !important;
  animation:         _skelShimmer 1.8s ease-in-out infinite !important;
}

/* Reveal stagger */
.appSkeletonReveal {
  animation: _skelFadeIn 380ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .appSkeletonReveal:nth-child(1)  { animation-delay: 0ms !important; }
.chkApp .appSkeletonReveal:nth-child(2)  { animation-delay: 45ms !important; }
.chkApp .appSkeletonReveal:nth-child(3)  { animation-delay: 90ms !important; }
.chkApp .appSkeletonReveal:nth-child(4)  { animation-delay: 135ms !important; }
.chkApp .appSkeletonReveal:nth-child(5)  { animation-delay: 180ms !important; }
.chkApp .appSkeletonReveal:nth-child(6)  { animation-delay: 225ms !important; }
.chkApp .appSkeletonReveal:nth-child(7)  { animation-delay: 270ms !important; }
.chkApp .appSkeletonReveal:nth-child(8)  { animation-delay: 315ms !important; }

/* Skeleton shapes */
.appSkeletonLine        { height: 0.75rem; }
.appSkeletonLineShort   { width: 38%; }
.appSkeletonLineMedium  { width: 62%; }
.appSkeletonLineLong    { width: 88%; }
.appSkeletonTitle       { height: 1.1rem; width: 55%; border-radius: 0.4rem !important; }
.appSkeletonCircle      { border-radius: 50% !important; }
.appSkeletonCard        {
  height:       7rem;
  border-radius:1rem !important;
  border:       1px solid rgba(var(--hz-accent-rgb, 0,112,242), 0.06);
}

/* ══════════════════════════════════════════════════════════════
   CH 5 · ENTRY ANIMATIONS — cards, list rows, table rows
   ══════════════════════════════════════════════════════════════ */

@keyframes _cardEnter {
  from { opacity: 0; transform: translateY(10px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes _rowEnter {
  from { opacity: 0; transform: translateX(-6px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* KPI / Analytics cards */
.chkApp .kpiCard,
.chkApp .searchAnalyticsCard,
.chkApp .workflowStageCard {
  animation: _cardEnter 320ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .kpiCard:nth-child(1),
.chkApp .searchAnalyticsCard:nth-child(1) { animation-delay: 0ms !important; }
.chkApp .kpiCard:nth-child(2),
.chkApp .searchAnalyticsCard:nth-child(2) { animation-delay: 55ms !important; }
.chkApp .kpiCard:nth-child(3),
.chkApp .searchAnalyticsCard:nth-child(3) { animation-delay: 110ms !important; }
.chkApp .kpiCard:nth-child(4),
.chkApp .searchAnalyticsCard:nth-child(4) { animation-delay: 165ms !important; }
.chkApp .kpiCard:nth-child(5),
.chkApp .searchAnalyticsCard:nth-child(5) { animation-delay: 220ms !important; }
.chkApp .kpiCard:nth-child(6),
.chkApp .searchAnalyticsCard:nth-child(6) { animation-delay: 275ms !important; }

/* Table rows — slide in from left */
.chkApp .searchResultsTable .sapMListTblRow {
  animation: _rowEnter 260ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .searchResultsTable .sapMListTblRow:nth-child(1)  { animation-delay: 0ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(2)  { animation-delay: 28ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(3)  { animation-delay: 56ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(4)  { animation-delay: 84ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(5)  { animation-delay: 112ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(6)  { animation-delay: 140ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(7)  { animation-delay: 168ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(8)  { animation-delay: 196ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(n+9){ animation-delay: 220ms !important; }

/* List items */
.chkApp .sapMLIB {
  animation: _rowEnter 240ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .sapMLIB:nth-child(1)  { animation-delay: 0ms !important; }
.chkApp .sapMLIB:nth-child(2)  { animation-delay: 32ms !important; }
.chkApp .sapMLIB:nth-child(3)  { animation-delay: 64ms !important; }
.chkApp .sapMLIB:nth-child(4)  { animation-delay: 96ms !important; }
.chkApp .sapMLIB:nth-child(5)  { animation-delay: 128ms !important; }
.chkApp .sapMLIB:nth-child(n+6){ animation-delay: 150ms !important; }

/* ══════════════════════════════════════════════════════════════
   CH 6 · MICRO-INTERACTIONS — ripple, input pulse, chip hover
   ══════════════════════════════════════════════════════════════ */

/* ── Button ripple (CSS only, on active) ── */

@keyframes _ripple {
  from { transform: scale(0) translate(-50%, -50%); opacity: 0.4; }
  to   { transform: scale(4) translate(-50%, -50%); opacity: 0; }
}

.chkApp .sapMBtn {
  position: relative;
  overflow: visible !important;
}

.chkApp .sapMBtn .sapMBtnInner {
  isolation: isolate !important;
}

/* Pseudo-ripple on active — inside clip */
.chkApp .sapMBtn:not(.sapMBtnDisabled):active .sapMBtnInner::before {
  content:       '';
  position:      absolute;
  width:         10px;
  height:        10px;
  top:           50%;
  left:          50%;
  border-radius: 50%;
  background:    rgba(255, 255, 255, 0.40);
  animation:     _ripple 380ms ease-out forwards;
  pointer-events:none;
  z-index:       0;
}

body.chkAppRoot.appDark .chkApp .sapMBtn:not(.sapMBtnDisabled):active .sapMBtnInner::before {
  background: rgba(255, 255, 255, 0.22);
}

/* ── Input focus glow pulse ── */

@keyframes _inputFocusPulse {
  0%   { box-shadow: 0 0 0 0 rgba(var(--hz-accent-rgb, 0,112,242), 0.24); }
  60%  { box-shadow: 0 0 0 5px rgba(var(--hz-accent-rgb, 0,112,242), 0.0); }
  100% { box-shadow: 0 0 0 3px rgba(var(--hz-accent-rgb, 0,112,242), 0.16); }
}

.chkApp .sapMInputBaseContentWrapper:focus-within {
  animation: _inputFocusPulse 350ms ease both !important;
}

/* ── Chip / badge pop on mount ── */

@keyframes _chipPop {
  0%   { transform: scale(0.80); opacity: 0; }
  70%  { transform: scale(1.06); opacity: 1; }
  100% { transform: scale(1);    opacity: 1; }
}

.chkApp .detailRailStatusChip,
.chkApp .searchSelectionStatusChip,
.chkApp .searchSummaryStatusChip,
.chkApp .searchStageStatusChip,
.chkApp .detailWorkflowChip {
  animation: _chipPop 320ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* ── Segment button selected indicator pulse ── */

@keyframes _segSelPop {
  0%   { opacity: 0; }
  60%  { opacity: 1; transform: scaleX(1.04); }
  100% { opacity: 1; transform: scaleX(1); }
}

.chkApp .sapMSegBBtn.sapMSegBBtnSel {
  animation: _segSelPop 200ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 7 · STATUS ICON PICTOGRAMS — semantic shapes + animated badge
   ══════════════════════════════════════════════════════════════ */

/* ── Semantic icon color system ── */

/* Error icon — red */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-negative"],
.chkApp .sapMObjStatusStateNegative .sapUiIcon,
.chkApp [data-sap-icon="status-negative"] {
  color:     var(--hz-danger, #CC0000) !important;
  font-size: 1.05em !important;
}

/* Success icon — green */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-positive"],
.chkApp .sapMObjStatusStatePositive .sapUiIcon,
.chkApp [data-sap-icon="status-positive"] {
  color:     var(--hz-success, #1A7C40) !important;
  font-size: 1.05em !important;
}

/* Warning icon — amber */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-critical"],
.chkApp .sapMObjStatusStateCritical .sapUiIcon,
.chkApp [data-sap-icon="status-critical"] {
  color:     var(--hz-warning, #C35500) !important;
  font-size: 1.05em !important;
}

/* Info icon — accent blue */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-information"],
.chkApp .sapMObjStatusStateInformation .sapUiIcon,
.chkApp [data-sap-icon="status-information"] {
  color:     var(--hz-accent, var(--accent)) !important;
  font-size: 1.05em !important;
}

/* ── Global icon alignment ── */

.chkApp .sapUiIcon {
  display:      inline-flex !important;
  align-items:  center !important;
  justify-content: center !important;
  flex-shrink:  0 !important;
  line-height:  1 !important;
  vertical-align: middle !important;
}

/* ── Attention icon pulse ── */

@keyframes _iconAttention {
  0%, 100% { transform: scale(1); }
  20%       { transform: scale(1.22) rotate(-8deg); }
  40%       { transform: scale(1.18) rotate(6deg); }
  60%       { transform: scale(1.14) rotate(-4deg); }
  80%       { transform: scale(1.10) rotate(2deg); }
}

.chkApp .iconAttention {
  animation: _iconAttention 0.6s ease both;
  animation-delay: 400ms;
}

/* ── Notification badge ── */

.chkApp .shellNotificationBadge,
.chkApp .notifBadge {
  position:       absolute !important;
  top:            -0.2rem !important;
  right:          -0.2rem !important;
  min-width:      1rem !important;
  height:         1rem !important;
  padding:        0 0.22rem !important;
  border-radius:  999px !important;
  font-size:      0.6rem !important;
  font-weight:    800 !important;
  line-height:    1rem !important;
  text-align:     center !important;
  color:          #fff !important;
  background:     var(--hz-danger, #CC0000) !important;
  border:         2px solid !important;
  animation:      _badgePop 350ms cubic-bezier(0.22, 0.61, 0.36, 1) both,
                  _badgePulse 3s 1s ease-in-out infinite !important;
  z-index:        9 !important;
}

body.chkAppRoot.appLight .chkApp .shellNotificationBadge {
  border-color: rgba(255, 255, 255, 0.95) !important;
}

body.chkAppRoot.appDark .chkApp .shellNotificationBadge {
  border-color: rgba(14, 26, 48, 0.95) !important;
}

@keyframes _badgePop {
  from { transform: scale(0); opacity: 0; }
  70%  { transform: scale(1.15); opacity: 1; }
  to   { transform: scale(1);   opacity: 1; }
}

@keyframes _badgePulse {
  0%,  80%, 100% { box-shadow: 0 0 0 0 rgba(204,0,0,0); }
  40%             { box-shadow: 0 0 0 4px rgba(204,0,0,0.18); }
}

/* ── Icon-in-chip status coloring ── */

.chkApp .detailRailStatusChip .sapUiIcon,
.chkApp .searchSelectionStatusChip .sapUiIcon,
.chkApp .searchSummaryStatusChip .sapUiIcon {
  flex-shrink: 0 !important;
  font-size:   0.78rem !important;
}

/* ── Workflow chip icon ── */

.chkApp .detailWorkflowChip .sapUiIcon {
  font-size:   0.75rem !important;
  opacity:     0.82 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 8 · KPI NUMBER — count-up reveal animation
   ══════════════════════════════════════════════════════════════ */

@keyframes _kpiReveal {
  from {
    opacity:   0;
    transform: translateY(8px) scale(0.92);
    filter:    blur(2px);
  }
  to {
    opacity:   1;
    transform: translateY(0) scale(1);
    filter:    blur(0);
  }
}

.chkApp .kpiCard .sapMTitle,
.chkApp .kpiCard .kpiNumber,
.chkApp .kpiCard .sapMObjectNumberText {
  animation: _kpiReveal 420ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  animation-delay: 80ms !important;
}

/* Trend indicator entrance */
@keyframes _trendSlide {
  from { opacity: 0; transform: translateX(-6px); }
  to   { opacity: 1; transform: translateX(0); }
}

.chkApp .kpiCard .kpiTrend,
.chkApp .kpiCard .kpiTrendPositive,
.chkApp .kpiCard .kpiTrendNegative {
  animation: _trendSlide 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  animation-delay: 160ms !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 9 · TOAST / NOTIFICATION — choreography
   ══════════════════════════════════════════════════════════════ */

@keyframes _toastIn {
  from {
    opacity:   0;
    transform: translateY(12px) scale(0.96);
  }
  80% {
    transform: translateY(-2px) scale(1.005);
  }
  to {
    opacity:   1;
    transform: translateY(0) scale(1);
  }
}

@keyframes _toastOut {
  to {
    opacity:   0;
    transform: translateY(8px) scale(0.95);
    filter:    blur(2px);
  }
}

.sapMMessageToast {
  border-radius: 0.875rem !important;
  border:        1.5px solid !important;
  font-size:     0.845rem !important;
  font-weight:   600 !important;
  padding:       0.6rem 1rem !important;
  animation:     _toastIn 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  box-shadow:    0 8px 28px rgba(12, 28, 52, 0.15) !important;
}

body.chkAppRoot.appLight .sapMMessageToast {
  background:   rgba(255, 255, 255, 0.98) !important;
  border-color: rgba(118, 162, 218, 0.45) !important;
  color:        rgba(24, 44, 80, 0.92) !important;
}

body.chkAppRoot.appDark .sapMMessageToast {
  background:   rgba(20, 34, 60, 0.98) !important;
  border-color: rgba(77, 177, 255, 0.22) !important;
  color:        rgba(210, 228, 252, 0.92) !important;
}

/* Semantic toast variants */
.sapMMessageToast.sapMMessageToastError {
  border-color: var(--hz-danger-border, rgba(204,0,0,0.32)) !important;
  background:   rgba(255, 245, 245, 0.99) !important;
}

body.chkAppRoot.appDark .sapMMessageToast.sapMMessageToastError {
  background:   rgba(40, 12, 18, 0.98) !important;
  border-color: rgba(255, 92, 119, 0.28) !important;
}

.sapMMessageToast.sapMMessageToastSuccess {
  border-color: var(--hz-success-border, rgba(26,124,64,0.32)) !important;
  background:   rgba(245, 253, 248, 0.99) !important;
}

body.chkAppRoot.appDark .sapMMessageToast.sapMMessageToastSuccess {
  background:   rgba(8, 32, 18, 0.98) !important;
  border-color: rgba(93, 193, 34, 0.28) !important;
}

/* Left semantic stripe */
.sapMMessageToast::before {
  content:      '';
  position:     absolute;
  left:         0;
  top:          0.25rem;
  bottom:       0.25rem;
  width:        3px;
  border-radius:999px;
  background:   var(--hz-accent, var(--accent));
}

.sapMMessageToast.sapMMessageToastError::before   { background: var(--hz-danger, #CC0000); }
.sapMMessageToast.sapMMessageToastSuccess::before { background: var(--hz-success, #1A7C40); }

/* ══════════════════════════════════════════════════════════════
   CH 10 · DIALOG / POPOVER — spring entrance per type
   ══════════════════════════════════════════════════════════════ */

@keyframes _dialogSpring {
  0%   { opacity: 0; transform: scale(0.90) translateY(16px); }
  70%  { transform: scale(1.012) translateY(-2px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes _popoverSlide {
  from { opacity: 0; transform: translateY(6px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes _selectDrop {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

.sapMDialog:not(.sapMBusyDialog) {
  animation: _dialogSpring 300ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.sapMPopover,
.sapMResponsivePopover {
  animation: _popoverSlide 200ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.sapMSelectList,
.sapMComboBoxBasePicker {
  animation: _selectDrop 160ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* Dialog scrim fade */
.sapMDialogBlockLayer,
.sapUiBLy {
  animation: _scrimIn 220ms ease both !important;
}

@keyframes _scrimIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ══════════════════════════════════════════════════════════════
   CH 11 · ICON TAB BAR — animated underline indicator
   ══════════════════════════════════════════════════════════════ */

/* Selected tab underline */
.chkApp .sapMITBSelected .sapMITBText::after {
  content:       '';
  position:      absolute;
  bottom:        -1px;
  left:          0;
  right:         0;
  height:        2px;
  border-radius: 999px 999px 0 0;
  background:    var(--hz-accent, var(--accent));
  animation:     _tabUnderlineIn 200ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  transform-origin: center;
}

@keyframes _tabUnderlineIn {
  from { transform: scaleX(0); opacity: 0; }
  to   { transform: scaleX(1); opacity: 1; }
}

.chkApp .sapMITBText {
  position: relative !important;
}

/* Tab hover */
.chkApp .sapMITBFilter:not(.sapMITBSelected):hover .sapMITBText {
  color:      var(--hz-accent, var(--accent)) !important;
  transition: color 140ms ease !important;
}

/* Tab count badge */
.chkApp .sapMITBCount {
  font-size:      0.65rem !important;
  font-weight:    700 !important;
  border-radius:  999px !important;
  padding:        0 0.32rem !important;
  min-width:      1.1rem !important;
  text-align:     center !important;
  line-height:    1.35 !important;
  animation:      _badgePop 300ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

body.chkAppRoot.appLight .chkApp .sapMITBSelected .sapMITBCount {
  background:   rgba(var(--hz-accent-rgb, 0,112,242), 0.12) !important;
  color:        var(--hz-accent, #0070F2) !important;
}

body.chkAppRoot.appDark .chkApp .sapMITBSelected .sapMITBCount {
  background:   rgba(var(--hz-accent-rgb, 77,177,255), 0.16) !important;
  color:        var(--hz-accent, #4DB1FF) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 12 · PAGE TRANSITIONS
   ══════════════════════════════════════════════════════════════ */

@keyframes _pageIn {
  from { opacity: 0; transform: translateX(18px); }
  to   { opacity: 1; transform: translateX(0); }
}

@keyframes _pageBack {
  from { opacity: 0; transform: translateX(-12px); }
  to   { opacity: 1; transform: translateX(0); }
}

.chkApp .sapMNavContainer .sapMPage {
  animation: _pageIn 260ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .sapMNavContainer .sapMPage.sapMNavBack {
  animation: _pageBack 220ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* Detail pane reveal */
@keyframes _detailPaneIn {
  from { opacity: 0; transform: translateX(24px); }
  to   { opacity: 1; transform: translateX(0); }
}

.chkApp .detailMainExperienceStack {
  animation: _detailPaneIn 300ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 13 · DATA UPDATE FLASH — when values change
   ══════════════════════════════════════════════════════════════ */

@keyframes _dataFlashPositive {
  0%   { background: rgba(var(--hz-success-rgb, 26,124,64), 0.0); }
  25%  { background: rgba(var(--hz-success-rgb, 26,124,64), 0.14); }
  100% { background: rgba(var(--hz-success-rgb, 26,124,64), 0.0); }
}

@keyframes _dataFlashNegative {
  0%   { background: rgba(var(--hz-danger-rgb, 204,0,0), 0.0); }
  25%  { background: rgba(var(--hz-danger-rgb, 204,0,0), 0.12); }
  100% { background: rgba(var(--hz-danger-rgb, 204,0,0), 0.0); }
}

@keyframes _dataFlashNeutral {
  0%   { background: rgba(var(--hz-accent-rgb, 0,112,242), 0.0); }
  25%  { background: rgba(var(--hz-accent-rgb, 0,112,242), 0.10); }
  100% { background: rgba(var(--hz-accent-rgb, 0,112,242), 0.0); }
}

/* Apply with JS: element.classList.add('dataUpdated') etc. */
.chkApp .dataUpdatedPositive { animation: _dataFlashPositive 800ms ease both; }
.chkApp .dataUpdatedNegative { animation: _dataFlashNegative 800ms ease both; }
.chkApp .dataUpdated         { animation: _dataFlashNeutral  600ms ease both; }

/* Table row update flash */
.chkApp .sapMListTblRow.dataUpdated .sapMListTblCell {
  animation: _dataFlashNeutral 600ms ease both !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 14 · REDUCED MOTION — all animation killed cleanly
   ══════════════════════════════════════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  /* Kill all motion-based animations */
  .chkApp *,
  .chkApp *::before,
  .chkApp *::after,
  .sapMDialog,
  .sapMPopover,
  .sapMSelectList,
  .sapMMessageToast,
  .sapMBusyDialog,
  .sapUiLocalBusyIndicator,
  .appSkeleton,
  .appSkeletonReveal {
    animation-duration:        1ms !important;
    animation-delay:           0ms !important;
    transition-duration:       1ms !important;
  }

  /* Keep functional busy animations — remove decorative ones */
  .chkApp .sapMBusyIndicatorDot {
    animation-duration: 1.2s !important;    /* keep bounce, just instant */
    animation-delay:    0ms !important;
  }

  /* Kill transforms for users who are sensitive */
  .chkApp .kpiCard:hover,
  .chkApp .searchAnalyticsCard:hover,
  .chkApp .sapMBtn:hover .sapMBtnInner {
    transform: none !important;
    filter:    none !important;
  }

  /* Keep progress-bar busy — it's functional */
  .chkApp .busyBar::after {
    animation-duration: 1.4s !important;
  }
}

/* ================================================================
   9C_polish.css — Deep Polish · Missing Components · Visual Depth
   ================================================================
   Ch 1   Typography depth — fluid scale, optical spacing
   Ch 2   Surface hierarchy — 5-level elevation system
   Ch 3   Object Page (sapUxAP) — header, anchor bar, sections
   Ch 4   Illustrated empty states — per-context
   Ch 5   Avatar + avatar stack
   Ch 6   Rating indicator — stars
   Ch 7   Carousel
   Ch 8   Object List Item
   Ch 9   Object Marker / Attribute
   Ch 10  Action Sheet
   Ch 11  Quick View
   Ch 12  Upload Collection
   Ch 13  Color Palette picker
   Ch 14  Step Input
   Ch 15  Smart Form / SimpleForm
   Ch 16  Panel / Accordion — polished expand
   Ch 17  Data visualization polish
   Ch 18  Filter bar density
   Ch 19  Object Identifier / Object Number
   Ch 20  Shell header — depth + product brand cluster
   Ch 21  Responsive layout — better breakpoints
   Ch 22  Print — production ready
   ================================================================ */

/* ══════════════════════════════════════════════════════════════
   CH 1 · TYPOGRAPHY DEPTH
   Fluid scale: 10 levels, optical corrections, line-height rhythm
   ══════════════════════════════════════════════════════════════ */

:root {
  /* Fluid type scale */
  --t-2xs:  clamp(0.60rem, 0.58rem + 0.1vw, 0.66rem);
  --t-xs:   clamp(0.70rem, 0.68rem + 0.1vw, 0.75rem);
  --t-sm:   clamp(0.78rem, 0.76rem + 0.12vw, 0.84rem);
  --t-base: clamp(0.875rem, 0.86rem + 0.08vw, 0.9375rem);
  --t-md:   clamp(1.0rem, 0.96rem + 0.2vw, 1.1rem);
  --t-lg:   clamp(1.12rem, 1.05rem + 0.35vw, 1.3rem);
  --t-xl:   clamp(1.3rem, 1.18rem + 0.6vw, 1.62rem);
  --t-2xl:  clamp(1.55rem, 1.35rem + 1.0vw, 2.0rem);
  --t-3xl:  clamp(1.85rem, 1.55rem + 1.5vw, 2.6rem);
  --t-4xl:  clamp(2.2rem, 1.8rem + 2.0vw, 3.4rem);

  /* Line-height tokens */
  --lh-tight:  1.15;
  --lh-snug:   1.3;
  --lh-base:   1.5;
  --lh-relaxed:1.65;

  /* Letter-spacing */
  --ls-tight:  -0.022em;
  --ls-snug:   -0.012em;
  --ls-base:    0;
  --ls-wide:    0.025em;
  --ls-caps:    0.08em;

  /* Optical weight corrections */
  --fw-light:  320;
  --fw-normal: 420;
  --fw-medium: 540;
  --fw-semi:   630;
  --fw-bold:   720;
  --fw-heavy:  800;
  --fw-black:  900;
}

/* Base body font */
.chkApp {
  font-size:        var(--t-base) !important;
  line-height:      var(--lh-base) !important;
  letter-spacing:   var(--ls-base) !important;
  -webkit-font-smoothing: antialiased !important;
  -moz-osx-font-smoothing: grayscale !important;
  text-rendering:   optimizeLegibility !important;
  font-feature-settings: "kern" 1, "liga" 1 !important;
}

/* Heading hierarchy */
.chkApp .sapMTitle.sapMTitleStyleH1,
.chkApp .sapMTitle[data-sap-ui-type="Title"][level="H1"] {
  font-size:      var(--t-3xl) !important;
  font-weight:    var(--fw-heavy) !important;
  line-height:    var(--lh-tight) !important;
  letter-spacing: var(--ls-tight) !important;
}

.chkApp .sapMTitle.sapMTitleStyleH2,
.chkApp .sapMTitle[level="H2"] {
  font-size:      var(--t-2xl) !important;
  font-weight:    var(--fw-bold) !important;
  line-height:    var(--lh-snug) !important;
  letter-spacing: var(--ls-snug) !important;
}

.chkApp .sapMTitle.sapMTitleStyleH3,
.chkApp .sapMTitle[level="H3"] {
  font-size:      var(--t-xl) !important;
  font-weight:    var(--fw-semi) !important;
  line-height:    var(--lh-snug) !important;
}

.chkApp .sapMTitle.sapMTitleStyleH4,
.chkApp .sapMTitle[level="H4"] {
  font-size:      var(--t-lg) !important;
  font-weight:    var(--fw-semi) !important;
  line-height:    var(--lh-base) !important;
}

.chkApp .sapMTitle.sapMTitleStyleH5,
.chkApp .sapMTitle[level="H5"] {
  font-size:      var(--t-md) !important;
  font-weight:    var(--fw-medium) !important;
}

.chkApp .sapMLabel {
  font-size:      var(--t-sm) !important;
  font-weight:    var(--fw-medium) !important;
  line-height:    var(--lh-snug) !important;
  letter-spacing: var(--ls-wide) !important;
}

.chkApp .sapMText {
  font-size:   var(--t-base) !important;
  line-height: var(--lh-relaxed) !important;
}

/* Tabular numbers everywhere data appears */
.chkApp .sapMObjectNumber,
.chkApp .sapMListTblCell .sapMText[data-sap-ui*="number"],
.chkApp .sapMListTblCell .sapMObjectNumber,
.chkApp .kpiNumber,
.chkApp .analyticsValue {
  font-variant-numeric: tabular-nums !important;
  font-feature-settings: "tnum" 1, "kern" 1 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 2 · SURFACE HIERARCHY — 5-level elevation
   Level 0: body/background  (darkest in dark, lightest in light)
   Level 1: card surface      (main content blocks)
   Level 2: toolbar / rail    (toolbar bars, filter bar)
   Level 3: overlay           (popovers, dropdowns)
   Level 4: modal             (dialogs)
   ══════════════════════════════════════════════════════════════ */

body.chkAppRoot.appLight {
  --surf-0: rgba(236, 244, 255, 0.80);   /* body bg tint */
  --surf-1: rgba(255, 255, 255, 0.99);   /* cards */
  --surf-2: rgba(247, 251, 255, 0.99);   /* toolbars */
  --surf-3: rgba(255, 255, 255, 1.00);   /* dropdowns */
  --surf-4: rgba(255, 255, 255, 1.00);   /* dialogs */

  --elev-1: 0 1px 3px rgba(12, 28, 52, 0.05),
            0 1px 1px rgba(12, 28, 52, 0.03),
            inset 0 1px 0 rgba(255, 255, 255, 0.8);
  --elev-2: 0 2px 8px rgba(12, 28, 52, 0.07),
            0 1px 2px rgba(12, 28, 52, 0.04);
  --elev-3: 0 4px 16px rgba(12, 28, 52, 0.10),
            0 1px 4px rgba(12, 28, 52, 0.06);
  --elev-4: 0 12px 40px rgba(12, 28, 52, 0.14),
            0 3px 10px rgba(12, 28, 52, 0.08);

  --border-0: rgba(190, 210, 240, 0.45);
  --border-1: rgba(172, 198, 235, 0.55);
  --border-2: rgba(155, 185, 230, 0.65);
  --border-3: rgba(130, 168, 220, 0.55);
}

body.chkAppRoot.appDark {
  --surf-0: rgba(8, 15, 30, 0.90);
  --surf-1: rgba(16, 28, 52, 0.98);
  --surf-2: rgba(20, 34, 60, 0.98);
  --surf-3: rgba(22, 38, 66, 1.00);
  --surf-4: rgba(18, 32, 58, 1.00);

  --elev-1: 0 1px 3px rgba(0, 2, 12, 0.28),
            0 1px 1px rgba(0, 2, 12, 0.18),
            inset 0 1px 0 rgba(200, 224, 255, 0.04);
  --elev-2: 0 2px 8px rgba(0, 2, 12, 0.36),
            0 1px 2px rgba(0, 2, 12, 0.22);
  --elev-3: 0 4px 16px rgba(0, 2, 12, 0.44),
            0 1px 4px rgba(0, 2, 12, 0.28);
  --elev-4: 0 12px 40px rgba(0, 2, 12, 0.58),
            0 3px 10px rgba(0, 2, 12, 0.36);

  --border-0: rgba(60, 90, 140, 0.20);
  --border-1: rgba(70, 105, 160, 0.24);
  --border-2: rgba(77, 177, 255, 0.16);
  --border-3: rgba(77, 177, 255, 0.22);
}

/* Apply elevation to elements */
.chkApp .kpiCard,
.chkApp .searchAnalyticsCard,
.chkApp .workflowStageCard {
  background:   var(--surf-1) !important;
  box-shadow:   var(--elev-1) !important;
  border-color: var(--border-0) !important;
}

.chkApp .searchFilterCardDense,
.chkApp .searchResultsTable,
.chkApp .detailSectionCard,
.chkApp .detailInfoExperienceCard {
  background:   var(--surf-1) !important;
  box-shadow:   var(--elev-1) !important;
  border-color: var(--border-0) !important;
}

.chkApp .searchActionToolbarDensity,
.chkApp .searchSmartToolbarRail,
.chkApp .detailWorkflowRail,
.chkApp .detailControlRow {
  background:   var(--surf-2) !important;
  border-color: var(--border-1) !important;
}

.sapMPopover,
.sapMResponsivePopover,
.sapMSelectList {
  background:   var(--surf-3) !important;
  box-shadow:   var(--elev-3) !important;
  border:       1px solid var(--border-2) !important;
}

.sapMDialog {
  background:   var(--surf-4) !important;
  box-shadow:   var(--elev-4) !important;
  border:       1px solid var(--border-2) !important;
}

/* Card hover — elevation jump */
.chkApp .kpiCard:hover,
.chkApp .searchAnalyticsCard:hover,
.chkApp .workflowStageCard:hover {
  box-shadow:   var(--elev-2) !important;
  border-color: var(--border-2) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 3 · OBJECT PAGE (sapUxAP) — immersive layout
   ══════════════════════════════════════════════════════════════ */

/* ── Page container ── */
.chkApp .sapUxAPObjectPageLayout {
  background:    transparent !important;
  min-height:    100% !important;
}

/* ── Header ── */
.chkApp .sapUxAPObjectPageHeader {
  border-radius: 0 0 1rem 1rem !important;
  overflow:      hidden !important;
  margin-bottom: 0.5rem !important;
}

body.chkAppRoot.appLight .chkApp .sapUxAPObjectPageHeader {
  background:    var(--surf-1) !important;
  border-bottom: 1px solid var(--border-0) !important;
  box-shadow:    var(--elev-1) !important;
}

body.chkAppRoot.appDark .chkApp .sapUxAPObjectPageHeader {
  background:    var(--surf-1) !important;
  border-bottom: 1px solid var(--border-1) !important;
  box-shadow:    var(--elev-2) !important;
}

/* Header title */
.chkApp .sapUxAPObjectPageHeaderTitle,
.chkApp .sapUxAPObjectPageHeaderIdentifier {
  font-size:      var(--t-2xl) !important;
  font-weight:    var(--fw-heavy) !important;
  letter-spacing: var(--ls-tight) !important;
  line-height:    var(--lh-tight) !important;
}

/* Breadcrumb in header */
.chkApp .sapUxAPObjectPageHeader .sapMBreadcrumbs {
  font-size: var(--t-xs) !important;
  opacity:   0.75 !important;
}

/* ── Anchor bar ── */
.chkApp .sapUxAPAnchorBar {
  position:    sticky !important;
  top:         0 !important;
  z-index:     20 !important;
  border-radius:0 !important;
  transition:  box-shadow 200ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapUxAPAnchorBar {
  background:  rgba(255, 255, 255, 0.96) !important;
  border-bottom: 1px solid var(--border-0) !important;
  box-shadow:  0 2px 8px rgba(12, 28, 52, 0.06) !important;
}

body.chkAppRoot.appDark .chkApp .sapUxAPAnchorBar {
  background:  rgba(14, 26, 48, 0.97) !important;
  border-bottom: 1px solid var(--border-1) !important;
  box-shadow:  0 2px 12px rgba(0, 2, 14, 0.36) !important;
}

/* Anchor tab text */
.chkApp .sapUxAPAnchorBar .sapMITBText {
  font-size:   var(--t-sm) !important;
  font-weight: var(--fw-medium) !important;
}

/* Section header */
.chkApp .sapUxAPObjectPageSectionHeader {
  padding-block: 0.6rem 0.4rem !important;
}

.chkApp .sapUxAPObjectPageSection > .sapUxAPObjectPageSectionHeader .sapMTitle {
  font-size:      var(--t-md) !important;
  font-weight:    var(--fw-bold) !important;
  letter-spacing: var(--ls-snug) !important;
  position:       relative !important;
  padding-bottom: 0.5rem !important;
}

.chkApp .sapUxAPObjectPageSection > .sapUxAPObjectPageSectionHeader .sapMTitle::after {
  content:      '';
  position:     absolute;
  bottom:       0;
  left:         0;
  width:        2rem;
  height:       2px;
  border-radius:999px;
  background:   var(--hz-accent, var(--accent));
  opacity:      0.7;
  transition:   width 200ms ease;
}

.chkApp .sapUxAPObjectPageSection:hover > .sapUxAPObjectPageSectionHeader .sapMTitle::after {
  width: 3.5rem;
}

/* SubSection */
.chkApp .sapUxAPObjectPageSubSection {
  padding-block: 0.75rem 1rem !important;
}

.chkApp .sapUxAPObjectPageSubSectionHeader .sapMTitle {
  font-size:   var(--t-sm) !important;
  font-weight: var(--fw-semi) !important;
  text-transform: uppercase !important;
  letter-spacing: var(--ls-caps) !important;
  opacity:     0.65 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 4 · ILLUSTRATED EMPTY STATES
   ══════════════════════════════════════════════════════════════ */

@keyframes _illusFloat {
  0%,  100% { transform: translateY(0);    }
  50%        { transform: translateY(-6px); }
}

@keyframes _illusIn {
  from { opacity: 0; transform: scale(0.90) translateY(12px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* SAP illustrated message */
.chkApp .sapMIllustratedMessage,
.chkApp .detailEmptyStateCard,
.chkApp .detailChecksEmptyState,
.chkApp .detailBarriersEmptyState,
.chkApp .detailAttachmentsEmptyState {
  display:         flex !important;
  flex-direction:  column !important;
  align-items:     center !important;
  justify-content: center !important;
  text-align:      center !important;
  padding:         2.5rem 2rem !important;
  gap:             0.75rem !important;
  animation:       _illusIn 380ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* SVG illustration */
.chkApp .sapMIllustratedMessage .sapMIllustratedMessageImage,
.chkApp .sapMIllustratedMessage svg,
.chkApp .sapMIllustratedMessage img {
  max-width:     180px !important;
  max-height:    140px !important;
  opacity:       0.88 !important;
  animation:     _illusFloat 4s ease-in-out infinite !important;
}

/* Title */
.chkApp .sapMIllustratedMessage .sapMIllustratedMessageTitle,
.chkApp .detailEmptyStateTitle {
  font-size:      var(--t-lg) !important;
  font-weight:    var(--fw-bold) !important;
  letter-spacing: var(--ls-snug) !important;
  line-height:    var(--lh-tight) !important;
}

body.chkAppRoot.appLight .chkApp .sapMIllustratedMessage .sapMIllustratedMessageTitle,
body.chkAppRoot.appLight .chkApp .detailEmptyStateTitle {
  color: rgba(30, 50, 84, 0.88) !important;
}

body.chkAppRoot.appDark .chkApp .sapMIllustratedMessage .sapMIllustratedMessageTitle,
body.chkAppRoot.appDark .chkApp .detailEmptyStateTitle {
  color: rgba(200, 220, 252, 0.90) !important;
}

/* Description */
.chkApp .sapMIllustratedMessage .sapMIllustratedMessageDescription,
.chkApp .detailEmptyStateText {
  font-size:   var(--t-sm) !important;
  line-height: var(--lh-relaxed) !important;
  max-width:   28rem !important;
  opacity:     0.65 !important;
}

/* No-data in table */
.chkApp .sapMListNoData {
  padding:         2.5rem 1.5rem !important;
  text-align:      center !important;
  animation:       _illusIn 360ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .sapMListNoDataIcon {
  font-size:    2.8rem !important;
  opacity:      0.28 !important;
  margin-bottom:0.5rem !important;
  display:      block !important;
}

.chkApp .sapMListNoDataText {
  font-size:     var(--t-sm) !important;
  font-weight:   var(--fw-semi) !important;
  line-height:   var(--lh-base) !important;
}

body.chkAppRoot.appLight .chkApp .sapMListNoDataText {
  color: rgba(80, 112, 165, 0.75) !important;
}

body.chkAppRoot.appDark .chkApp .sapMListNoDataText {
  color: rgba(var(--hz-accent-rgb, 77,177,255), 0.50) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 5 · AVATAR — sizes, shapes, stacks
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMAvatar {
  border-radius:  50% !important;
  overflow:       hidden !important;
  flex-shrink:    0 !important;
  font-weight:    var(--fw-bold) !important;
  display:        inline-flex !important;
  align-items:    center !important;
  justify-content:center !important;
  position:       relative !important;
  transition:     box-shadow 160ms ease, transform 160ms ease !important;
}

/* Size variants */
.chkApp .sapMAvatar.sapMAvatarSizeXS { width: 1.5rem;  height: 1.5rem;  font-size: 0.56rem !important; }
.chkApp .sapMAvatar.sapMAvatarSizeS  { width: 2.0rem;  height: 2.0rem;  font-size: 0.72rem !important; }
.chkApp .sapMAvatar.sapMAvatarSizeM  { width: 2.75rem; height: 2.75rem; font-size: 1.0rem  !important; }
.chkApp .sapMAvatar.sapMAvatarSizeL  { width: 3.5rem;  height: 3.5rem;  font-size: 1.25rem !important; }
.chkApp .sapMAvatar.sapMAvatarSizeXL { width: 4.5rem;  height: 4.5rem;  font-size: 1.65rem !important; }

/* Square variant */
.chkApp .sapMAvatar.sapMAvatarTypeSquare {
  border-radius: 0.55rem !important;
}

/* Color variants */
.chkApp .sapMAvatar.sapMAvatarColor1  { background: rgba(0, 112, 242, 0.15) !important; color: #0058C8 !important; }
.chkApp .sapMAvatar.sapMAvatarColor2  { background: rgba(93, 193, 34, 0.15) !important; color: #2E7D00 !important; }
.chkApp .sapMAvatar.sapMAvatarColor3  { background: rgba(255, 92, 119, 0.15) !important; color: #B80000 !important; }
.chkApp .sapMAvatar.sapMAvatarColor4  { background: rgba(255, 179, 0, 0.15) !important; color: #8A4A00 !important; }
.chkApp .sapMAvatar.sapMAvatarColor5  { background: rgba(120, 100, 220, 0.15) !important; color: #4A2E9A !important; }
.chkApp .sapMAvatar.sapMAvatarColor6  { background: rgba(0, 170, 160, 0.15) !important; color: #006860 !important; }

body.chkAppRoot.appDark .chkApp .sapMAvatar.sapMAvatarColor1 { background: rgba(77, 177, 255, 0.18) !important; color: #7AC8FF !important; }
body.chkAppRoot.appDark .chkApp .sapMAvatar.sapMAvatarColor2 { background: rgba(93, 193, 34, 0.18)  !important; color: #8DE040 !important; }
body.chkAppRoot.appDark .chkApp .sapMAvatar.sapMAvatarColor3 { background: rgba(255, 92, 119, 0.18) !important; color: #FF8FA4 !important; }

/* Hover */
.chkApp .sapMAvatar:hover {
  transform:  scale(1.06) !important;
  box-shadow: 0 4px 12px rgba(var(--hz-accent-rgb, 0,112,242), 0.20) !important;
  z-index:    1 !important;
}

/* ── Avatar stack ── */
.chkApp .sapMAvatarGroup {
  display:     inline-flex !important;
  align-items: center !important;
}

.chkApp .sapMAvatarGroup .sapMAvatar {
  border:      2px solid !important;
  margin-left: -0.6rem !important;
  transition:  transform 150ms ease, margin 150ms ease !important;
}

.chkApp .sapMAvatarGroup .sapMAvatar:first-child { margin-left: 0 !important; }

body.chkAppRoot.appLight .chkApp .sapMAvatarGroup .sapMAvatar {
  border-color: rgba(255, 255, 255, 0.90) !important;
}

body.chkAppRoot.appDark .chkApp .sapMAvatarGroup .sapMAvatar {
  border-color: rgba(16, 28, 52, 0.90) !important;
}

.chkApp .sapMAvatarGroup:hover .sapMAvatar {
  margin-left: -0.4rem !important;
}

/* Overflow badge */
.chkApp .sapMAvatarGroup .sapMAvatarGroupOverflow {
  background:   rgba(var(--hz-accent-rgb, 0,112,242), 0.14) !important;
  color:        var(--hz-accent, var(--accent)) !important;
  font-weight:  var(--fw-bold) !important;
  font-size:    var(--t-xs) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 6 · RATING INDICATOR — stars
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMRI {
  display:     inline-flex !important;
  align-items: center !important;
  gap:         0.18rem !important;
}

.chkApp .sapMRIIcon {
  font-size:   1.1rem !important;
  line-height: 1 !important;
  cursor:      pointer !important;
  transition:  color 120ms ease, transform 120ms ease !important;
  display:     inline-flex !important;
}

/* Filled */
.chkApp .sapMRIIconSel,
.chkApp .sapMRIIcon.sapMRIIconSel {
  color:     #F5A623 !important;
}

/* Hover — all stars before cursor glow */
.chkApp .sapMRI:not(.sapMRIReadOnly) .sapMRIIcon:hover,
.chkApp .sapMRI:not(.sapMRIReadOnly) .sapMRIIcon:hover ~ .sapMRIIcon {
  color:     rgba(245, 166, 35, 0.55) !important;
}

.chkApp .sapMRI:not(.sapMRIReadOnly) .sapMRIIcon:hover {
  transform: scale(1.2) !important;
  color:     #F5A623 !important;
}

/* Unselected */
.chkApp .sapMRIIconUnsel,
.chkApp .sapMRIIcon.sapMRIIconUnsel {
  color:     rgba(200, 210, 228, 0.7) !important;
}

body.chkAppRoot.appDark .chkApp .sapMRIIconUnsel {
  color:     rgba(80, 106, 152, 0.6) !important;
}

/* Read-only — no hover */
.chkApp .sapMRIReadOnly .sapMRIIcon {
  cursor: default !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 7 · CAROUSEL
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMCrsl {
  position:      relative !important;
  overflow:      hidden !important;
  border-radius: 1rem !important;
}

.chkApp .sapMCrslInner {
  display:    flex !important;
  transition: transform 360ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

.chkApp .sapMCrslItem {
  flex:       0 0 100% !important;
  min-width:  0 !important;
}

/* Navigation arrows */
.chkApp .sapMCrslPrev,
.chkApp .sapMCrslNext {
  position:        absolute !important;
  top:             50% !important;
  transform:       translateY(-50%) !important;
  width:           2.4rem !important;
  height:          2.4rem !important;
  border-radius:   50% !important;
  border:          0 !important;
  display:         flex !important;
  align-items:     center !important;
  justify-content: center !important;
  cursor:          pointer !important;
  z-index:         2 !important;
  transition:      background 140ms ease, transform 160ms ease !important;
  opacity:         0.85 !important;
}

.chkApp .sapMCrslPrev { left:  0.5rem !important; }
.chkApp .sapMCrslNext { right: 0.5rem !important; }

body.chkAppRoot.appLight .chkApp .sapMCrslPrev,
body.chkAppRoot.appLight .chkApp .sapMCrslNext {
  background: rgba(255, 255, 255, 0.90) !important;
  box-shadow: var(--elev-2) !important;
  color:      var(--hz-accent, #0070F2) !important;
}

body.chkAppRoot.appDark .chkApp .sapMCrslPrev,
body.chkAppRoot.appDark .chkApp .sapMCrslNext {
  background: rgba(22, 38, 68, 0.92) !important;
  box-shadow: var(--elev-2) !important;
  color:      var(--hz-accent, #4DB1FF) !important;
}

.chkApp .sapMCrslPrev:hover { transform: translateY(-50%) scale(1.1) !important; opacity: 1 !important; }
.chkApp .sapMCrslNext:hover { transform: translateY(-50%) scale(1.1) !important; opacity: 1 !important; }

/* Page indicator dots */
.chkApp .sapMCrslBulleted,
.chkApp .sapMCrslPageIndicator {
  display:         flex !important;
  justify-content: center !important;
  align-items:     center !important;
  gap:             0.4rem !important;
  padding-top:     0.6rem !important;
}

.chkApp .sapMCrslBulleted > span,
.chkApp .sapMCrslPageIndicatorItem {
  width:         0.45rem !important;
  height:        0.45rem !important;
  border-radius: 50% !important;
  transition:    width 200ms ease, background 200ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMCrslBulleted > span {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.25) !important;
}

body.chkAppRoot.appLight .chkApp .sapMCrslBulleted > span.sapMCrslActive {
  background: var(--hz-accent, #0070F2) !important;
  width:      1.0rem !important;
  border-radius: 999px !important;
}

body.chkAppRoot.appDark .chkApp .sapMCrslBulleted > span {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.28) !important;
}

body.chkAppRoot.appDark .chkApp .sapMCrslBulleted > span.sapMCrslActive {
  background: var(--hz-accent, #4DB1FF) !important;
  width:      1.0rem !important;
  border-radius: 999px !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 8 · OBJECT LIST ITEM
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMOLI {
  border-radius: 0.6rem !important;
  padding:       0.6rem 0.75rem !important;
  margin:        1px 0 !important;
  transition:    background 110ms ease !important;
  position:      relative !important;
}

body.chkAppRoot.appLight .chkApp .sapMOLI:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

body.chkAppRoot.appDark .chkApp .sapMOLI:hover {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.05) !important;
}

.chkApp .sapMOLI.sapMLIBSelected {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.08) !important;
}

.chkApp .sapMOLI.sapMLIBSelected::before {
  content:      '';
  position:     absolute;
  left:         0;
  top:          0.3rem;
  bottom:       0.3rem;
  width:        3px;
  border-radius:0 999px 999px 0;
  background:   var(--hz-accent, var(--accent));
}

/* Title / Description */
.chkApp .sapMOLITitle {
  font-size:   var(--t-base) !important;
  font-weight: var(--fw-semi) !important;
  line-height: var(--lh-snug) !important;
}

.chkApp .sapMOLIDescription {
  font-size:   var(--t-sm) !important;
  line-height: var(--lh-base) !important;
  opacity:     0.70 !important;
}

/* Number */
.chkApp .sapMOLINumber {
  font-size:            var(--t-base) !important;
  font-weight:          var(--fw-bold) !important;
  font-variant-numeric: tabular-nums !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 9 · OBJECT MARKER + OBJECT ATTRIBUTE
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMObjectMarker {
  display:       inline-flex !important;
  align-items:   center !important;
  gap:           0.22rem !important;
  font-size:     var(--t-xs) !important;
  font-weight:   var(--fw-medium) !important;
  border-radius: 999px !important;
  padding:       0.15rem 0.5rem !important;
  border:        1px solid !important;
  transition:    background 130ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMObjectMarker {
  background:   rgba(0, 112, 242, 0.07) !important;
  border-color: rgba(0, 112, 242, 0.22) !important;
  color:        rgba(0, 64, 180, 0.90) !important;
}

body.chkAppRoot.appDark .chkApp .sapMObjectMarker {
  background:   rgba(77, 177, 255, 0.10) !important;
  border-color: rgba(77, 177, 255, 0.24) !important;
  color:        rgba(120, 196, 255, 0.90) !important;
}

.chkApp .sapMObjectMarker .sapUiIcon {
  font-size: 0.75rem !important;
  opacity:   0.80 !important;
}

/* Object Attribute */
.chkApp .sapMObjectAttr {
  display:  flex !important;
  gap:      0.22rem !important;
}

.chkApp .sapMObjectAttrTitle {
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-medium) !important;
  opacity:     0.60 !important;
}

.chkApp .sapMObjectAttrText {
  font-size:   var(--t-sm) !important;
  font-weight: var(--fw-semi) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 10 · ACTION SHEET — mobile bottom sheet style
   ══════════════════════════════════════════════════════════════ */

@keyframes _actionSheetIn {
  from { transform: translateY(100%); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.sapMActionSheet {
  border-radius:  1.25rem 1.25rem 0 0 !important;
  overflow:       hidden !important;
  animation:      _actionSheetIn 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  padding-bottom: env(safe-area-inset-bottom, 0.5rem) !important;
}

body.chkAppRoot.appLight .sapMActionSheet {
  background:   rgba(255, 255, 255, 0.99) !important;
  box-shadow:   0 -8px 28px rgba(12, 28, 52, 0.12) !important;
  border-top:   1px solid var(--border-0) !important;
}

body.chkAppRoot.appDark .sapMActionSheet {
  background:   rgba(18, 30, 54, 0.99) !important;
  box-shadow:   0 -8px 28px rgba(0, 2, 14, 0.44) !important;
  border-top:   1px solid var(--border-1) !important;
}

/* Drag handle */
.sapMActionSheet::before {
  content:       '';
  display:       block;
  width:         2.5rem;
  height:        0.25rem;
  border-radius: 999px;
  margin:        0.6rem auto 0.4rem;
  background:    rgba(0, 0, 0, 0.16);
}

body.chkAppRoot.appDark .sapMActionSheet::before {
  background: rgba(255, 255, 255, 0.18);
}

/* Buttons inside */
.sapMActionSheet .sapMBtn .sapMBtnInner {
  border-radius: 0.75rem !important;
  min-height:    2.75rem !important;
  font-size:     var(--t-base) !important;
  justify-content: flex-start !important;
  padding:       0 1.2rem !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 11 · QUICK VIEW
   ══════════════════════════════════════════════════════════════ */

.sapMQuickView,
.sapMQuickViewPage {
  border-radius: 1rem !important;
  overflow:      hidden !important;
}

.sapMQuickViewHeader {
  padding:       0.875rem 1rem 0.75rem !important;
  border-bottom: 1px solid var(--border-0) !important;
}

body.chkAppRoot.appLight .sapMQuickViewHeader {
  background: rgba(246, 250, 255, 0.99) !important;
}

body.chkAppRoot.appDark .sapMQuickViewHeader {
  background: rgba(20, 34, 60, 0.99) !important;
}

/* Avatar in quick view header */
.sapMQuickViewHeader .sapMAvatar {
  width:  2.75rem !important;
  height: 2.75rem !important;
}

/* Quick view form rows */
.sapMQuickViewGroupElement {
  display:       grid !important;
  grid-template-columns: 38% 62% !important;
  align-items:   baseline !important;
  gap:           0.25rem !important;
  padding:       0.4rem 1rem !important;
  border-radius: 0.4rem !important;
  transition:    background 100ms ease !important;
}

.sapMQuickViewGroupElement:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

.sapMQuickViewGroupElementLabel {
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-medium) !important;
  opacity:     0.60 !important;
  white-space: nowrap !important;
}

.sapMQuickViewGroupElementValue {
  font-size:   var(--t-sm) !important;
  font-weight: var(--fw-semi) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 12 · UPLOAD COLLECTION
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMUC {
  border-radius: 0.875rem !important;
  overflow:      hidden !important;
}

/* Drop zone */
.chkApp .sapMUCNoDataPage,
.chkApp .sapMUCDragDropOverlay {
  border:          2px dashed !important;
  border-radius:   0.875rem !important;
  display:         flex !important;
  flex-direction:  column !important;
  align-items:     center !important;
  justify-content: center !important;
  gap:             0.5rem !important;
  padding:         2rem !important;
  transition:      border-color 150ms ease, background 150ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMUCNoDataPage {
  border-color: rgba(118, 162, 218, 0.45) !important;
  background:   rgba(246, 250, 255, 0.60) !important;
}

body.chkAppRoot.appDark .chkApp .sapMUCNoDataPage {
  border-color: rgba(77, 177, 255, 0.22) !important;
  background:   rgba(16, 28, 52, 0.60) !important;
}

.chkApp .sapMUCNoDataPage:hover,
.chkApp .sapMUCDragActive .sapMUCNoDataPage {
