body.chkAppRoot.appLight .chkApp .sapMUCItem:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

body.chkAppRoot.appDark .chkApp .sapMUCItem:hover {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.05) !important;
}

/* ══════════════════════════════════════════════════════════════
