   ══════════════════════════════════════════════════════════════ */

.chkApp .sapUiForm,
.chkApp .sapUiSimpleForm {
  container-type: inline-size !important;
}

/* Form group header */
.chkApp .sapUiFormTitle,
.chkApp .sapUiSimpleFormTitle {
  font-size:      var(--t-sm) !important;
  font-weight:    var(--fw-heavy) !important;
  letter-spacing: var(--ls-caps) !important;
  text-transform: uppercase !important;
