}

/* Validation message */
.chkApp .sapMInputBase .sapMInputBaseMessageIcon {
  color: var(--hz-danger, #CC0000) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 15 · PANEL / ACCORDION — polished expand animation
   ══════════════════════════════════════════════════════════════ */

@keyframes _panelExpand {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.chkApp .sapMPanel {
  border-radius: 0.875rem !important;
  overflow:      hidden !important;
  border:        1px solid var(--border-0) !important;
  transition:    box-shadow 180ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMPanel {
  background:  var(--surf-1) !important;
  box-shadow:  var(--elev-1) !important;
}

body.chkAppRoot.appDark .chkApp .sapMPanel {
  background:  var(--surf-1) !important;
  box-shadow:  var(--elev-1) !important;
}

/* Panel header */
.chkApp .sapMPanelHdr {
  padding:     0.6rem 0.875rem !important;
  cursor:      pointer !important;
  user-select: none !important;
  display:     flex !important;
  align-items: center !important;
  gap:         0.5rem !important;
  transition:  background 130ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMPanelHdr:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

body.chkAppRoot.appDark .chkApp .sapMPanelHdr:hover {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.05) !important;
}

.chkApp .sapMPanelHdrTitle {
  font-size:   var(--t-base) !important;
  font-weight: var(--fw-semi) !important;
  flex:        1 !important;
}

/* Expand icon */
.chkApp .sapMPanelExpandableIcon {
  color:      var(--hz-accent, var(--accent)) !important;
  opacity:    0.70 !important;
  transition: transform 240ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

.chkApp .sapMPanel.sapMPanelExpanded .sapMPanelExpandableIcon {
  transform: rotate(180deg) !important;
}

/* Content area */
.chkApp .sapMPanelContent {
  padding:    0.75rem 0.875rem !important;
  animation:  _panelExpand 220ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* Panel separator */
.chkApp .sapMPanel + .chkApp .sapMPanel {
  margin-top: 0.5rem !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 16 · DATA VISUALIZATION — chart cards & indicators
   ══════════════════════════════════════════════════════════════ */

/* Consistent chart card */
.chkApp .analyticsChartCard,
.chkApp .analyticsChartPanel {
  border-radius: 1rem !important;
  border:        1px solid var(--border-0) !important;
  overflow:      hidden !important;
}

body.chkAppRoot.appLight .chkApp .analyticsChartCard {
  background:  var(--surf-1) !important;
  box-shadow:  var(--elev-1) !important;
}

body.chkAppRoot.appDark .chkApp .analyticsChartCard {
  background:  var(--surf-1) !important;
  box-shadow:  var(--elev-1) !important;
}

/* Data label typography */
.chkApp .analyticsChartCard .sapMText,
.chkApp .analyticsValue {
  font-variant-numeric: tabular-nums !important;
  font-feature-settings: "tnum" 1 !important;
}

/* Legend chip */
.chkApp .analyticsLegendItem,
.chkApp .searchRateLegendItem {
  display:     inline-flex !important;
  align-items: center !important;
  gap:         0.3rem !important;
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-medium) !important;
}

/* Progress / rate bar */
.chkApp .analyticsRateBar,
.chkApp .searchRateBar {
  border-radius: 999px !important;
  overflow:      hidden !important;
  height:        6px !important;
}

.chkApp .analyticsRateFill,
.chkApp .searchRateFill {
  border-radius:  999px !important;
  height:         100% !important;
  transition:     width 600ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

/* KPI delta indicator */
.chkApp .kpiTrendPositive {
  color: var(--hz-success, #1A7C40) !important;
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-bold) !important;
}

.chkApp .kpiTrendNegative {
  color: var(--hz-danger, #CC0000) !important;
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-bold) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 17 · FILTER BAR DENSITY — compact, readable
   ══════════════════════════════════════════════════════════════ */

.chkApp .searchFilterCardDense .sapUiCompFilterBarItem {
  display:       flex !important;
  flex-direction:column !important;
  gap:           0.15rem !important;
}

/* Filter label */
.chkApp .searchFilterCardDense .sapUiCompFilterBarItemLabel,
.chkApp .searchFilterCardDense .sapUiCompSmartFilterBar .sapMLabel {
  font-size:      var(--t-2xs) !important;
  font-weight:    var(--fw-heavy) !important;
  letter-spacing: var(--ls-caps) !important;
  text-transform: uppercase !important;
  line-height:    1 !important;
  opacity:        0.60 !important;
}

/* Filter input — compact */
.chkApp .searchFilterCardDense .sapMInputBaseContentWrapper {
  min-height: 1.8rem !important;
  font-size:  var(--t-sm) !important;
}

/* "Show more / Less" button */
.chkApp .sapUiCompFilterBarShowAllFiltersBtn .sapMBtnInner,
.chkApp .sapUiCompFilterBarHideAllFiltersBtn .sapMBtnInner {
  font-size:   var(--t-xs) !important;
  padding:     0 0.6rem !important;
  min-height:  1.7rem !important;
  opacity:     0.80 !important;
  border-style:dashed !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 18 · OBJECT IDENTIFIER
   ══════════════════════════════════════════════════════════════ */

.chkApp .sapMObjectIdentifier {
  display:       flex !important;
  flex-direction:column !important;
  gap:           0.08rem !important;
}

.chkApp .sapMObjectIdentifierTitle {
  font-size:   var(--t-base) !important;
  font-weight: var(--fw-semi) !important;
  line-height: var(--lh-snug) !important;
  color:       var(--hz-accent, var(--accent)) !important;
  cursor:      pointer !important;
  transition:  opacity 120ms ease !important;
}

.chkApp .sapMObjectIdentifierTitle:hover { opacity: 0.80 !important; }

.chkApp .sapMObjectIdentifierText {
  font-size:   var(--t-xs) !important;
  line-height: var(--lh-base) !important;
  opacity:     0.65 !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 19 · SHELL HEADER — product cluster, depth
   ══════════════════════════════════════════════════════════════ */

/* Pinned shadow when scrolled */
.chkApp .appShellHeader.shellPinned {
  box-shadow:   0 2px 16px rgba(12, 28, 52, 0.12), 0 1px 4px rgba(12,28,52,0.06) !important;
  border-bottom:1px solid var(--border-1) !important;
}

body.chkAppRoot.appDark .chkApp .appShellHeader.shellPinned {
  box-shadow:   0 2px 16px rgba(0, 2, 14, 0.44), 0 1px 4px rgba(0,2,14,0.28) !important;
}

/* Product title — fluid size */
.chkApp .shellProductTitle {
  font-size:      clamp(0.92rem, 1.5vw, 1.12rem) !important;
  font-weight:    var(--fw-heavy) !important;
  letter-spacing: var(--ls-tight) !important;
  line-height:    var(--lh-tight) !important;
  white-space:    nowrap !important;
}

/* Eyebrow */
.chkApp .shellEyebrow {
  font-size:      var(--t-2xs) !important;
  font-weight:    var(--fw-heavy) !important;
  letter-spacing: var(--ls-caps) !important;
  text-transform: uppercase !important;
  opacity:        0.52 !important;
  line-height:    1 !important;
}

/* Shell context chip — subtle pill */
.chkApp .shellContextChip {
  padding:     0.18rem 0.65rem !important;
  font-size:   var(--t-xs) !important;
  font-weight: var(--fw-semi) !important;
  transition:  background 140ms ease, border-color 140ms ease !important;
}

.chkApp .shellContextChip:hover {
  border-color: var(--hz-accent-border, rgba(0,112,242,0.3)) !important;
}

/* Shell user button avatar */
.chkApp .shellUserBtn .sapMAvatar {
  width:  1.85rem !important;
  height: 1.85rem !important;
  font-size: 0.68rem !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 20 · RESPONSIVE — 5 breakpoints, better layouts
   ══════════════════════════════════════════════════════════════ */

/* ── ≥1440px: ultra-wide ── */
@media (min-width: 90rem) {
  .chkApp .searchAnalyticsRailGrid {
    grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr)) !important;
  }
}

/* ── ≤1280px: comfortable ── */
@media (max-width: 80rem) {
  .chkApp .kpiCard .sapMObjectNumberText {
    font-size: var(--t-xl) !important;
  }
}

/* ── ≤1024px: tablet landscape ── */
@media (max-width: 64rem) {
  .chkApp .shellProductTitle {
    font-size: 0.92rem !important;
  }

  .chkApp .shellContextRail {
    display: none !important;
  }

  .chkApp .searchFilterCardDense .sapUiCompFilterBar {
    flex-wrap: wrap !important;
  }
}

/* ── ≤768px: tablet portrait ── */
@media (max-width: 48rem) {
  .chkApp .searchAnalyticsRailGrid {
    grid-template-columns: repeat(2, 1fr) !important;
  }

  .chkApp .searchFilterCardDense {
    padding: 0.6rem 0.75rem !important;
  }

  /* Table columns — hide secondary */
  .chkApp .sapMListTblCell:nth-child(n+4):not(:last-child) {
    display: none !important;
  }

  /* Dialog — bottom sheet on mobile */
  .sapMDialog:not(.sapMBusyDialog) {
    border-radius:  1.25rem 1.25rem 0 0 !important;
    position:       fixed !important;
    bottom:         0 !important;
    left:           0 !important;
    right:          0 !important;
    top:            auto !important;
    max-height:     90dvh !important;
    transform:      none !important;
    margin:         0 !important;
    width:          100% !important;
  }
}

/* ── ≤480px: phone ── */
@media (max-width: 30rem) {
  .chkApp .searchAnalyticsRailGrid {
    grid-template-columns: 1fr 1fr !important;
  }

  .chkApp .sapMSegBBtnInner {
    padding: 0 0.5rem !important;
    font-size: 0.72rem !important;
  }

  .chkApp .appShellHeader {
    padding-inline: 0.75rem !important;
  }
}

/* ══════════════════════════════════════════════════════════════
   CH 21 · PRINT — production quality
   ══════════════════════════════════════════════════════════════ */

@media print {
  @page {
    margin: 2cm 1.8cm;
    size:   A4;
  }

  .chkApp {
    font-size:  10pt !important;
    color:      #000 !important;
    background: #fff !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  /* Hide non-content elements */
  .chkApp .appShellHeader,
  .chkApp .searchFilterCardDense,
  .chkApp .searchActionToolbarDensity,
  .chkApp .searchSmartToolbarRail,
  .chkApp .detailWorkflowRail,
  .chkApp .detailControlRow,
  .chkApp .sapMOTBOverflowButton,
  .chkApp .shellActionBtn,
  .chkApp .shellUserBtn,
  .chkApp .sapMBtnIconOnly {
    display: none !important;
  }

  /* Cards — flat, printable */
  .chkApp .kpiCard,
  .chkApp .searchResultsTable,
  .chkApp .detailSectionCard,
  .chkApp .detailInfoExperienceCard {
    box-shadow:    none !important;
    border:        0.75pt solid #ccc !important;
    background:    #fff !important;
    break-inside:  avoid !important;
    border-radius: 0 !important;
  }

  /* Table */
  .chkApp .sapMListTblHeaderCell {
    background:  #f0f0f0 !important;
    font-weight: bold !important;
    border-bottom: 1.5pt solid #999 !important;
  }

  .chkApp .sapMListTblRow .sapMListTblCell {
    border-bottom: 0.5pt solid #eee !important;
    background:    #fff !important;
  }

  .chkApp .sapMListTblRow:nth-child(even) .sapMListTblCell {
    background: #f9f9f9 !important;
  }

  /* Links — show URL */
  .chkApp .sapMLnk::after {
    content: ' (' attr(href) ')';
    font-size: 0.8em;
    opacity: 0.6;
  }

  /* Kill all animations */
  * {
    animation:  none !important;
    transition: none !important;
  }
}

/* ================================================================
   9D_depth.css  —  Deep UX Polish · Final Layer
   ================================================================
   Loads last → maximum specificity.

   Ch 1   Grid Table (sapUiTable) — full visual system
   Ch 2   Timeline — animated nodes, connectors, semantic icons
   Ch 3   Notification List — rich cards with actions
   Ch 4   Search Busy Pictograms — branded animation system
   Ch 5   Overflow Toolbar — overflow popover, action density
   Ch 6   Inline feedback — input value states, counter, hint text
   Ch 7   Status Chip system — size variants, animated badge
   Ch 8   Workflow pipeline — stage connector, progress arc
   Ch 9   KPI Rail — shimmer on update, micro sparkline
   Ch 10  Search Narrative Rail — result summary card
   Ch 11  Generic Tile — image tile, news tile, line tile
   Ch 12  Color — semantic token aliases for all remaining uses
   Ch 13  Scrollbar — context-aware, wider on touch
   Ch 14  Motion — page-level transition coordinator
   Ch 15  Accessibility polish — focus, skip links, ARIA live
   ================================================================ */

/* ══════════════════════════════════════════════════════════════
   CH 1 · GRID TABLE (sapUiTable) — deep visual system
   ══════════════════════════════════════════════════════════════ */

/* ── Table container ── */
.chkApp .sapUiTable {
  border-radius: 0.875rem !important;
  overflow:      hidden !important;
  border:        1px solid var(--border-0, rgba(190,210,240,0.45)) !important;
}

/* ── Column header row ── */
.chkApp .sapUiTableColHdrCnt {
  border-bottom:    2px solid var(--border-1, rgba(172,198,235,0.55)) !important;
  border-radius:    0 !important;
  position:         sticky !important;
  top:              0 !important;
  z-index:          10 !important;
}

body.chkAppRoot.appLight .chkApp .sapUiTableColHdrCnt {
  background: rgba(246, 250, 255, 0.99) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableColHdrCnt {
  background: rgba(18, 30, 54, 0.99) !important;
}

/* ── Column header cell ── */
.chkApp .sapUiTableColCell {
  font-size:      0.65rem !important;
  font-weight:    800 !important;
  letter-spacing: 0.09em !important;
  text-transform: uppercase !important;
  padding:        0 0.75rem !important;
  min-height:     2.2rem !important;
  vertical-align: middle !important;
  cursor:         pointer !important;
  user-select:    none !important;
  white-space:    nowrap !important;
  transition:     background 110ms ease, color 110ms ease !important;
  position:       relative !important;
}

body.chkAppRoot.appLight .chkApp .sapUiTableColCell {
  color: rgba(56, 85, 130, 0.75) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableColCell {
  color: rgba(var(--hz-accent-rgb, 77,177,255), 0.60) !important;
}

.chkApp .sapUiTableColCell:hover {
  color: var(--hz-accent, var(--accent)) !important;
}

body.chkAppRoot.appLight .chkApp .sapUiTableColCell:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableColCell:hover {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.05) !important;
}

/* Sort active column */
.chkApp .sapUiTableColSorted .sapUiTableColCell {
  color: var(--hz-accent, var(--accent)) !important;
}

.chkApp .sapUiTableColSorted .sapUiTableColCell::after {
  content:     '';
  position:    absolute;
  bottom:      0;
  left:        0.75rem;
  right:       0.75rem;
  height:      2px;
  border-radius: 999px 999px 0 0;
  background:  var(--hz-accent, var(--accent));
  opacity:     0.7;
}

/* Column resize handle */
.chkApp .sapUiTableColRsz {
  width:      3px !important;
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.0) !important;
  transition: background 140ms ease !important;
  cursor:     col-resize !important;
}

.chkApp .sapUiTableColCell:hover ~ .sapUiTableColRsz,
.chkApp .sapUiTableColRsz:hover {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.35) !important;
}

/* ── Table row ── */
.chkApp .sapUiTableTr {
  transition:  background 90ms ease !important;
  position:    relative !important;
}

body.chkAppRoot.appLight .chkApp .sapUiTableTr:nth-child(odd) .sapUiTableCell {
  background: rgba(255, 255, 255, 0.98) !important;
}

body.chkAppRoot.appLight .chkApp .sapUiTableTr:nth-child(even) .sapUiTableCell {
  background: rgba(246, 250, 255, 0.98) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableTr:nth-child(odd) .sapUiTableCell {
  background: rgba(16, 28, 52, 0.97) !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableTr:nth-child(even) .sapUiTableCell {
  background: rgba(20, 34, 60, 0.97) !important;
}

/* Row hover */
body.chkAppRoot.appLight .chkApp .sapUiTableTr:hover .sapUiTableCell {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.05) !important;
  cursor:     pointer !important;
}

body.chkAppRoot.appDark .chkApp .sapUiTableTr:hover .sapUiTableCell {
  background: rgba(var(--hz-accent-rgb, 77,177,255), 0.06) !important;
}

/* Row selected */
.chkApp .sapUiTableRowSel .sapUiTableCell,
.chkApp .sapUiTableTr.sapUiTableRowSel .sapUiTableCell {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.10) !important;
}

