/* ══════════════════════════════════════════════════════════════
   CH 2 · TIMELINE — animated, semantic, rich
   ══════════════════════════════════════════════════════════════ */

@keyframes _tlNodePop {
  0%   { transform: scale(0); opacity: 0; }
  65%  { transform: scale(1.2); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

@keyframes _tlLineDraw {
  from { transform: scaleY(0); transform-origin: top; }
  to   { transform: scaleY(1); }
}

@keyframes _tlItemSlide {
  from { opacity: 0; transform: translateX(-10px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* Container */
.chkApp .sapMTimeline {
  position:   relative !important;
  padding:    0 !important;
  overflow:   visible !important;
}

/* Vertical line */
.chkApp .sapMTimeline::before {
  content:         '' !important;
  position:        absolute !important;
  inset-block:     0.8rem 0.8rem !important;
  inset-inline-start: 1.08rem !important;
  width:           2px !important;
  border-radius:   999px !important;
  background:      linear-gradient(
    180deg,
    transparent 0%,
    rgba(var(--hz-accent-rgb, 0,112,242), 0.30) 8%,
    rgba(var(--hz-accent-rgb, 0,112,242), 0.22) 92%,
    transparent 100%
  ) !important;
  animation:       _tlLineDraw 600ms ease both !important;
  animation-delay: 100ms !important;
}

/* Item */
.chkApp .sapMTimelineItem {
  position:       relative !important;
  padding-inline-start: 3rem !important;
  padding-bottom: 1.25rem !important;
  border:         0 !important;
  background:     transparent !important;
  animation:      _tlItemSlide 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .sapMTimelineItem:nth-child(1) { animation-delay: 50ms !important; }
.chkApp .sapMTimelineItem:nth-child(2) { animation-delay: 110ms !important; }
.chkApp .sapMTimelineItem:nth-child(3) { animation-delay: 170ms !important; }
.chkApp .sapMTimelineItem:nth-child(4) { animation-delay: 230ms !important; }
.chkApp .sapMTimelineItem:nth-child(n+5) { animation-delay: 280ms !important; }

/* Node icon bubble */
.chkApp .sapMTimelineItemIcon {
  position:      absolute !important;
  inset-inline-start: 0.42rem !important;
  top:           0.2rem !important;
  width:         1.35rem !important;
  height:        1.35rem !important;
  border-radius: 50% !important;
  background:    var(--hz-accent, var(--accent)) !important;
  border:        2.5px solid !important;
  box-shadow:    0 0 0 3px rgba(var(--hz-accent-rgb, 0,112,242), 0.15) !important;
  z-index:       2 !important;
  display:       flex !important;
  align-items:   center !important;
  justify-content: center !important;
  animation:     _tlNodePop 360ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  flex-shrink:   0 !important;
  font-size:     0.6rem !important;
  color:         rgba(255,255,255,0.96) !important;
  transition:    box-shadow 160ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMTimelineItemIcon {
  border-color: rgba(255, 255, 255, 0.96) !important;
}

body.chkAppRoot.appDark .chkApp .sapMTimelineItemIcon {
  border-color: rgba(14, 26, 48, 0.96) !important;
}

/* Semantic node colours */
.chkApp .sapMTimelineItem.sapMTimelineItemPositive .sapMTimelineItemIcon {
  background: var(--hz-success, #1A7C40) !important;
  box-shadow: 0 0 0 3px rgba(var(--hz-success-rgb, 26,124,64), 0.18) !important;
}

.chkApp .sapMTimelineItem.sapMTimelineItemNegative .sapMTimelineItemIcon {
  background: var(--hz-danger, #CC0000) !important;
  box-shadow: 0 0 0 3px rgba(var(--hz-danger-rgb, 204,0,0), 0.18) !important;
}

.chkApp .sapMTimelineItem.sapMTimelineItemCritical .sapMTimelineItemIcon {
  background: var(--hz-warning, #C35500) !important;
  box-shadow: 0 0 0 3px rgba(var(--hz-warning-rgb, 195,85,0), 0.18) !important;
}

/* Node hover */
.chkApp .sapMTimelineItem:hover .sapMTimelineItemIcon {
  box-shadow:    0 0 0 5px rgba(var(--hz-accent-rgb, 0,112,242), 0.18) !important;
  transform:     scale(1.1) !important;
}

/* Content bubble */
.chkApp .sapMTimelineItemContent {
  border-radius: 0.75rem !important;
  border:        1px solid var(--border-0, rgba(190,210,240,0.45)) !important;
  padding:       0.65rem 0.875rem !important;
  font-size:     0.845rem !important;
  line-height:   1.55 !important;
  transition:    border-color 150ms ease, box-shadow 150ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMTimelineItemContent {
  background: rgba(255, 255, 255, 0.97) !important;
  box-shadow: 0 1px 3px rgba(12,28,52,0.05) !important;
}

body.chkAppRoot.appDark .chkApp .sapMTimelineItemContent {
  background: rgba(18, 30, 54, 0.97) !important;
  box-shadow: 0 1px 4px rgba(0,2,12,0.22) !important;
}

.chkApp .sapMTimelineItem:hover .sapMTimelineItemContent {
  border-color: rgba(var(--hz-accent-rgb, 0,112,242), 0.28) !important;
  box-shadow:   0 3px 10px rgba(var(--hz-accent-rgb, 0,112,242), 0.08) !important;
}

/* Title */
.chkApp .sapMTimelineItemTitle {
  font-size:      0.875rem !important;
  font-weight:    720 !important;
  letter-spacing: -0.01em !important;
  line-height:    1.25 !important;
  margin-bottom:  0.2rem !important;
}

/* Timestamp */
.chkApp .sapMTimelineItemDateTime {
  font-size:      0.72rem !important;
  font-weight:    540 !important;
  letter-spacing: 0.01em !important;
  opacity:        0.55 !important;
  margin-top:     0.35rem !important;
}

