/* ══════════════════════════════════════════════════════════════
   CH 4 · SEARCH BUSY PICTOGRAMS — elevated brand animation
   ══════════════════════════════════════════════════════════════ */

@keyframes _pictoFloat {
  0%,  100% { transform: translateY(0) rotate(0deg); }
  33%        { transform: translateY(-5px) rotate(2deg); }
  66%        { transform: translateY(-3px) rotate(-1.5deg); }
}

@keyframes _pictoGlow {
  0%,  100% { box-shadow: 0 0 0 0 rgba(var(--hz-accent-rgb, 0,112,242), 0.0); }
  50%        { box-shadow: 0 4px 16px rgba(var(--hz-accent-rgb, 0,112,242), 0.22); }
}

@keyframes _pictoOrbit {
  from { transform: rotate(0deg) translateX(0.35rem) rotate(0deg); }
  to   { transform: rotate(360deg) translateX(0.35rem) rotate(-360deg); }
}

/* Enhanced pictogram bubble */
.chkApp .searchBusyPictogram {
  display:         inline-flex !important;
  align-items:     center !important;
  justify-content: center !important;
  width:           3.2rem !important;
  height:          3.2rem !important;
  border-radius:   1rem !important;
  border:          1.5px solid !important;
  font-size:       1.3rem !important;
  position:        relative !important;
  cursor:          default !important;
  transition:      transform 200ms ease !important;
  animation:       _pictoFloat var(--_dur, 1.4s) ease-in-out infinite,
                   _pictoGlow  var(--_dur, 1.4s) ease-in-out infinite !important;
}

body.chkAppRoot.appLight .chkApp .searchBusyPictogram {
