  box-shadow:  0 2px 8px rgba(12,28,52,0.08) !important;
}

body.chkAppRoot.appDark .chkApp .searchBusyPictogram {
  background:  rgba(18, 32, 58, 0.96) !important;
  box-shadow:  0 2px 8px rgba(0,2,14,0.32) !important;
}

/* Coloured variants with per-theme border */
.chkApp .searchBusyPictogramOne {
  --_dur: 1.3s;
  border-color: rgba(0, 112, 242, 0.28) !important;
  color:        var(--hz-accent, #0070F2) !important;
