/* Skip link — hidden until focused */
.chkApp .skipLink,
.skipToMain {
  position:   absolute !important;
  top:        -100% !important;
  left:       0.5rem !important;
  z-index:    9999 !important;
  background: var(--hz-accent, #0070F2) !important;
  color:      #fff !important;
  padding:    0.5rem 1rem !important;
  border-radius: 0 0 0.5rem 0.5rem !important;
  font-size:  0.875rem !important;
  font-weight:700 !important;
  text-decoration: none !important;
  transition: top 120ms ease !important;
}

.chkApp .skipLink:focus,
.skipToMain:focus {
  top: 0 !important;
}

/* Improved visible focus on all interactive elements */
.chkApp a:focus-visible,
.chkApp button:focus-visible,
.chkApp [role="button"]:focus-visible,
.chkApp [role="option"]:focus-visible,
.chkApp [role="tab"]:focus-visible,
.chkApp [role="menuitem"]:focus-visible,
.chkApp [tabindex]:focus-visible {
  outline:       none !important;
  box-shadow:
    0 0 0 2px rgba(255,255,255,0.95),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 0,112,242), 0.66) !important;
  border-radius: inherit !important;
}

body.chkAppRoot.appDark .chkApp a:focus-visible,
body.chkAppRoot.appDark .chkApp [tabindex]:focus-visible {
