    0 0 0 2px rgba(8,16,36,0.96),
    0 0 0 4.5px rgba(var(--hz-accent-rgb, 77,177,255), 0.68) !important;
}

/* Aria live region flash */
@keyframes _liveRegionFlash {
  0%,  100% { outline: 2px solid transparent; }
  50%        { outline: 2px solid rgba(var(--hz-accent-rgb, 0,112,242), 0.30); }
}

[aria-live="assertive"]:not(:empty),
[aria-live="polite"]:not(:empty) {
  animation: _liveRegionFlash 600ms ease both;
}

/* Reduced transparency for users who need it */
@media (prefers-reduced-transparency: reduce) {
  body.chkAppRoot.appLight .chkApp .sapMInputBaseContentWrapper {
    background: rgba(255,255,255,0.96) !important;
  }
  body.chkAppRoot.appDark .chkApp .sapMInputBaseContentWrapper {
    background: rgba(22,36,64,0.96) !important;
  }
  body.chkAppRoot.appLight .chkApp .kpiCard {
    background: rgba(255,255,255,1.0) !important;
  }
  body.chkAppRoot.appDark .chkApp .kpiCard {
    background: rgba(18,30,54,1.0) !important;
  }
}

/* High contrast — solid borders everywhere */
@media (forced-colors: active) {
  .chkApp .sapMTimeline::before          { background: ButtonText !important; }
  .chkApp .sapMTimelineItemIcon          { forced-color-adjust: none; background: Highlight !important; }
  .chkApp .sapMNLI.sapMNLIUnread::before { background: Highlight !important; }
  .chkApp .workflowStageCard[data-stage-active]::before { background: Highlight !important; }
  .chkApp .sapUiTableColSorted .sapUiTableColCell::after { background: Highlight !important; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .chkApp .sapMTimelineItem,
  .chkApp .sapMTimeline::before,
  .chkApp .sapMTimelineItemIcon,
  .chkApp .sapMNLI,
  .chkApp .searchBusyPictogram,
  .chkApp .workflowStageCard::after,
  .chkApp .sapMGenericTile,
  .chkApp .sapMNLI:hover,
  .chkApp .sapMGenericTile:hover {
    animation:        none !important;
    transition-duration: 1ms !important;
    transform:        none !important;
  }

  .chkApp .kpiCard.kpiUpdated {
    animation: none !important;
  }
}

