}

/* Text above/below */
.chkApp .sapMPIText,
.chkApp .sapMPITextLeft,
.chkApp .sapMPITextRight {
  font-size:            0.70rem !important;
  font-weight:          700 !important;
  font-variant-numeric: tabular-nums !important;
  opacity:              0.72 !important;
}

/* Large variant */
.chkApp .sapMPILarge .sapMPIBar,
.chkApp .sapMPILarge {
  height: 0.8rem !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 3 · MICRO-CHARTS — styled stubs for SAP Suite charts
   ══════════════════════════════════════════════════════════════ */

/* ── Radial / Donut micro ── */

.chkApp .sapSuiteUiMicroChartRMC,
.chkApp [class*="RadialMicroChart"] {
  display:         inline-flex !important;
  align-items:     center !important;
  justify-content: center !important;
  position:        relative !important;
  overflow:        visible !important;
}

/* Donut track */
.chkApp .sapSuiteUiMicroChartRMCCircle,
.chkApp [class*="RadialMicroChart"] svg circle:first-child {
  stroke: rgba(var(--hz-accent-rgb, 0,112,242), 0.14) !important;
}

/* Donut fill */
.chkApp .sapSuiteUiMicroChartRMCCircleFull,
.chkApp [class*="RadialMicroChart"] svg circle:last-child {
  stroke: var(--hz-accent, var(--accent)) !important;
  stroke-linecap: round !important;
  transition: stroke-dashoffset 600ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

/* Positive (green) donut */
.chkApp [class*="RadialMicroChart"][data-state="Positive"] svg circle:last-child {
  stroke: var(--hz-success, #1A7C40) !important;
}

/* Negative (red) donut */
.chkApp [class*="RadialMicroChart"][data-state="Negative"] svg circle:last-child {
  stroke: var(--hz-danger, #CC0000) !important;
}

/* Inner label */
.chkApp .sapSuiteUiMicroChartRMCInnerContent {
  font-size:            0.62rem !important;
  font-weight:          800 !important;
  font-variant-numeric: tabular-nums !important;
}

/* ── Bullet micro ── */

.chkApp .sapSuiteUiMicroChartBMC,
.chkApp [class*="BulletMicroChart"] {
  height:        1.4rem !important;
  position:      relative !important;
  display:       flex !important;
  align-items:   center !important;
}

/* Forecast bar */
.chkApp .sapSuiteUiMicroChartBMCForecastBar {
  border-radius: 999px !important;
  height:        0.28rem !important;
  opacity:       0.35 !important;
  background:    var(--hz-accent, var(--accent)) !important;
}

/* Actual bar */
.chkApp .sapSuiteUiMicroChartBMCActualBar {
  border-radius: 999px !important;
  height:        0.55rem !important;
  background:    var(--hz-accent, var(--accent)) !important;
  animation:     _piBarGrow 500ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* Threshold line */
.chkApp .sapSuiteUiMicroChartBMCTargetBar {
  width:         2px !important;
  height:        1rem !important;
  border-radius: 1px !important;
  background:    rgba(var(--hz-accent-rgb, 0,112,242), 0.55) !important;
  position:      absolute !important;
}

/* ── Area micro ── */

.chkApp .sapSuiteUiMicroChartALMC svg,
.chkApp [class*="AreaMicroChart"] svg {
  overflow: visible !important;
}

.chkApp .sapSuiteUiMicroChartALMC path,
.chkApp [class*="AreaMicroChart"] path {
  stroke-width: 1.8 !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}

/* ── Harvey ball micro ── */

.chkApp [class*="HarveyBallMicroChart"] circle {
  transition: stroke-dashoffset 600ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

/* ══════════════════════════════════════════════════════════════
   CH 4 · SEARCH FIELD (sapMSF) — full 5-state system
   ══════════════════════════════════════════════════════════════ */

/* ── Global search field wrapper ── */
.chkApp .sapMSFF {
  border-radius: 0.6rem !important;
  border:        1.5px solid !important;
  overflow:      hidden !important;
  display:       inline-flex !important;
  align-items:   center !important;
  position:      relative !important;
  transition:
    border-color  150ms ease,
    box-shadow    150ms ease,
    background    150ms ease !important;
}

body.chkAppRoot.appLight .chkApp .sapMSFF {
  background:   rgba(255, 255, 255, 0.78) !important;
  border-color: rgba(118, 162, 218, 0.50) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSFF {
  background:   rgba(10, 20, 38, 0.45) !important;
  border-color: rgba(77, 177, 255, 0.22) !important;
}

/* State 1: hover */
body.chkAppRoot.appLight .chkApp .sapMSFF:hover {
  background:   rgba(255, 255, 255, 0.90) !important;
  border-color: rgba(0, 112, 242, 0.36) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSFF:hover {
  background:   rgba(14, 26, 50, 0.65) !important;
  border-color: rgba(77, 177, 255, 0.34) !important;
}

/* State 2: focus */
body.chkAppRoot.appLight .chkApp .sapMSFF:focus-within {
  background:   rgba(255, 255, 255, 0.98) !important;
  border-color: var(--hz-accent, #0070F2) !important;
  box-shadow:   0 0 0 3px rgba(0, 112, 242, 0.14) !important;
}

body.chkAppRoot.appDark .chkApp .sapMSFF:focus-within {
  background:   rgba(16, 28, 52, 0.88) !important;
  border-color: var(--hz-accent, #4DB1FF) !important;
  box-shadow:   0 0 0 3px rgba(77, 177, 255, 0.16) !important;
}

/* State 3: active (has value) */
.chkApp .sapMSFF.sapMSFVal {
  background: rgba(var(--hz-accent-rgb, 0,112,242), 0.04) !important;
}

/* State 4: busy/searching */
.chkApp .sapMSFF.sapMSFBSy::after {
  content:       '';
  position:      absolute;
  bottom:        0;
  left:          0;
  right:         0;
  height:        2px;
  background:    linear-gradient(
    90deg,
    transparent,
    var(--hz-accent, var(--accent)),
    transparent
  );
  background-size: 60% 100%;
  animation:     _busyBarSlide 1.2s ease-in-out infinite;
}

/* State 5: disabled */
.chkApp .sapMSFF.sapMSFDis {
  opacity: 0.45 !important;
  pointer-events: none !important;
}

/* Input inside */
.chkApp .sapMSFI {
  background:   transparent !important;
  border:       0 !important;
  font-size:    0.875rem !important;
  font-weight:  480 !important;
  flex:         1 !important;
  min-width:    0 !important;
  padding:      0 0.5rem !important;
}

/* Placeholder */
.chkApp .sapMSFI::placeholder {
  font-weight: 440 !important;
  opacity:     0.52 !important;
}

/* Search icon */
.chkApp .sapMSFR,
.chkApp .sapMSFB {
  flex-shrink:  0 !important;
  display:      flex !important;
  align-items:  center !important;
  justify-content: center !important;
  width:        2rem !important;
  height:       100% !important;
  cursor:       pointer !important;
  opacity:      0.60 !important;
  transition:   opacity 130ms ease, color 130ms ease !important;
}

.chkApp .sapMSFR:hover,
.chkApp .sapMSFB:hover {
  opacity: 1 !important;
  color:   var(--hz-accent, var(--accent)) !important;
}

