body.chkAppRoot.appDark .chkApp .sapMPlanCalApp.sapUiCalendarAppType01 { background: rgba(77,177,255,0.18) !important;  color: #9BCFFF !important; }
body.chkAppRoot.appDark .chkApp .sapMPlanCalApp.sapUiCalendarAppType02 { background: rgba(93,193,34,0.18)  !important;  color: #9EE650 !important; }
body.chkAppRoot.appDark .chkApp .sapMPlanCalApp.sapUiCalendarAppType03 { background: rgba(255,92,119,0.16) !important;  color: #FF9CAE !important; }

/* Today highlight */
.chkApp .sapMPlanCalRowHead.sapUiCalCurrentDate,
.sapMPlanCalRowHead.sapUiCalCurrentDate {
  color:      var(--hz-accent, var(--accent)) !important;
