}

/* ══════════════════════════════════════════════════════════════
   CH 7 · DETAIL PANE SECTIONS — entry + inner polish
   ══════════════════════════════════════════════════════════════ */

@keyframes _detailSectionIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Section cards entry — stagger */
.chkApp .detailMainExperienceStack > * {
  animation: _detailSectionIn 300ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

.chkApp .detailMainExperienceStack > *:nth-child(1) { animation-delay: 0ms !important; }
.chkApp .detailMainExperienceStack > *:nth-child(2) { animation-delay: 55ms !important; }
.chkApp .detailMainExperienceStack > *:nth-child(3) { animation-delay: 110ms !important; }
.chkApp .detailMainExperienceStack > *:nth-child(4) { animation-delay: 165ms !important; }
.chkApp .detailMainExperienceStack > *:nth-child(5) { animation-delay: 220ms !important; }
.chkApp .detailMainExperienceStack > *:nth-child(n+6) { animation-delay: 260ms !important; }

/* Info card tiles inner grid */
.chkApp .infoCardTile {
  contain:  layout style !important;
  position: relative !important;
  overflow: hidden !important;
}

/* Subtle inner shine ::before */
.chkApp .infoCardTile::before {
  content:        '';
  position:       absolute;
  inset:          0;
  border-radius:  inherit;
  background:     linear-gradient(135deg, rgba(255,255,255,0.06) 0%, transparent 55%);
  pointer-events: none;
  z-index:        0;
  opacity:        0;
  transition:     opacity 200ms ease;
}

body.chkAppRoot.appLight .chkApp .infoCardTile:hover::before { opacity: 1; }
body.chkAppRoot.appDark  .chkApp .infoCardTile:hover::before { opacity: 0.7; }

/* Detail section inner table row improvements */
.chkApp .detailSectionCard .sapMListTblRow .sapMListTblCell {
  padding-block: 0.45rem !important;
  font-size:     0.84rem !important;
}

/* Detail header title */
.chkApp .detailHeaderStack .sapMTitle,
.chkApp .detailObjectHeaderTitle {
  font-size:      clamp(1.15rem, 2vw, 1.55rem) !important;
  font-weight:    800 !important;
  letter-spacing: -0.022em !important;
  line-height:    1.18 !important;
}

/* Detail sub-id / secondary line */
.chkApp .detailObjectHeaderSubtitle,
.chkApp .detailHeaderStack .sapMObjectIdentifierText {
  font-size:   0.78rem !important;
  font-weight: 520 !important;
  opacity:     0.58 !important;
  margin-top:  0.12rem !important;
}

