/* ══════════════════════════════════════════════════════════════
   CH 1 · KPI Cards — complete visual system remaster
   Structure: kpiCard > kpiLabelRow(kpiLabelIcon + kpiLabel)
              + appSkeletonMetric | Title.H4 + searchAnalyticsMeta
   ══════════════════════════════════════════════════════════════ */

/* Card container */
.chkApp .kpiCard.searchAnalyticsCard {
  display:        flex !important;
  flex-direction: column !important;
  gap:            0 !important;
  padding:        1rem 1.1rem 0.9rem !important;
  min-width:      160px !important;
  flex:           1 1 160px !important;
  max-width:      240px !important;
  border-radius:  1rem !important;
  border:         1px solid !important;
  position:       relative !important;
  overflow:       hidden !important;
  cursor:         default !important;
  transition:     transform 160ms cubic-bezier(0.22,0.61,0.36,1),
                  box-shadow 160ms ease !important;
}

/* Subtle top-edge accent line */
.chkApp .kpiCard.searchAnalyticsCard::before {
  content:       '' !important;
  position:      absolute !important;
  inset:         0 0 auto 0 !important;
  height:        2px !important;
  border-radius: 1rem 1rem 0 0 !important;
  background:    linear-gradient(90deg,
    rgba(var(--hz-accent-rgb, 0,112,242), 0.55) 0%,
    transparent 100%) !important;
  pointer-events:none !important;
}

body.chkAppRoot.appLight .chkApp .kpiCard.searchAnalyticsCard {
  background:   rgba(255, 255, 255, 0.86) !important;
  border-color: rgba(160, 200, 240, 0.50) !important;
  box-shadow:
    0 1px 4px rgba(12, 28, 52, 0.07),
    inset 0 1px 0 rgba(255, 255, 255, 0.70) !important;
}

body.chkAppRoot.appDark .chkApp .kpiCard.searchAnalyticsCard {
  background:   rgba(14, 24, 46, 0.82) !important;
  border-color: rgba(55, 90, 155, 0.34) !important;
  box-shadow:
    0 1px 6px rgba(0, 2, 18, 0.40),
    inset 0 1px 0 rgba(100, 160, 255, 0.06) !important;
}

.chkApp .kpiCard.searchAnalyticsCard:hover {
  transform: translateY(-2px) !important;
}

body.chkAppRoot.appLight .chkApp .kpiCard.searchAnalyticsCard:hover {
  box-shadow:
    0 6px 20px rgba(0, 112, 242, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.80) !important;
}

body.chkAppRoot.appDark .chkApp .kpiCard.searchAnalyticsCard:hover {
