/* ══════════════════════════════════════════════════════════════
   CH 7 · Skeleton System — shimmer + structure
   ══════════════════════════════════════════════════════════════ */

@keyframes _skShimmer {
  0%   { background-position: -400px 0; }
  100% { background-position:  400px 0; }
}

/* Base skeleton line */
.chkApp .appSkeleton.appSkeletonLine {
  border-radius: 0.4rem !important;
  height:        0.75rem !important;
  animation:     _skShimmer 1.4s ease-in-out infinite !important;
}

body.chkAppRoot.appLight .chkApp .appSkeleton {
  background:
    linear-gradient(
      90deg,
      rgba(196, 215, 240, 0.55) 25%,
      rgba(255, 255, 255, 0.85) 50%,
      rgba(196, 215, 240, 0.55) 75%
    ) !important;
  background-size: 800px 100% !important;
}

body.chkAppRoot.appDark .chkApp .appSkeleton {
  background:
    linear-gradient(
      90deg,
      rgba(30, 50, 90, 0.70) 25%,
      rgba(60, 90, 150, 0.40) 50%,
      rgba(30, 50, 90, 0.70) 75%
    ) !important;
  background-size: 800px 100% !important;
}

/* Column widths */
.chkApp .appSkeletonLine.appSkeletonLineShort  { width: 4rem !important; }
.chkApp .appSkeletonLine.appSkeletonLineMedium { width: 7rem !important; }
.chkApp .appSkeletonLine.appSkeletonLineLong   { width: 11rem !important; }

/* Table skeleton */
.chkApp .appSkeletonTableSection,
.chkApp .appSkeletonTableShell {
  display:        flex !important;
  flex-direction: column !important;
  gap:            0.5rem !important;
  padding:        0.75rem !important;
}

.chkApp .appSkeletonTableHeader,
.chkApp .appSkeletonTableRow {
  display:     flex !important;
  align-items: center !important;
  gap:         0.75rem !important;
  padding:     0.4rem 0 !important;
}

.chkApp .appSkeletonTableHeader {
  border-bottom: 1px solid !important;
  padding-bottom:0.55rem !important;
  margin-bottom: 0.25rem !important;
}

body.chkAppRoot.appLight .chkApp .appSkeletonTableHeader {
  border-color: rgba(160, 200, 240, 0.30) !important;
}

body.chkAppRoot.appDark .chkApp .appSkeletonTableHeader {
  border-color: rgba(55, 85, 145, 0.22) !important;
}

/* Header skeleton lines — slightly taller */
.chkApp .appSkeletonTableHeader .appSkeletonLine {
  height:  0.65rem !important;
  opacity: 0.65 !important;
}

/* Col widths */
.chkApp .appSkeletonColSelect  { width: 2rem !important;  flex-shrink: 0 !important; }
.chkApp .appSkeletonColMain    { flex: 2 1 6rem !important; }
.chkApp .appSkeletonColStatus  { width: 5rem !important;  flex-shrink: 0 !important; }
.chkApp .appSkeletonColComment { flex: 3 1 8rem !important; }
.chkApp .appSkeletonColMeta    { width: 6rem !important;  flex-shrink: 0 !important; }

/* Form skeleton */
.chkApp .appSkeletonFormSection {
  display:        flex !important;
  flex-direction: column !important;
  gap:            0.6rem !important;
  padding:        0.875rem !important;
}

.chkApp .appSkeletonFormSectionInline .appSkeletonTableHeader,
.chkApp .appSkeletonFormSectionInline .appSkeletonTableRow {
  gap: 1rem !important;
}

/* Metric skeleton (inside kpiCard) */
.chkApp .appSkeletonMetric .appSkeletonLine:first-child {
  height: 1.8rem !important;
  width:  5rem !important;
}

.chkApp .appSkeletonMetric .appSkeletonLine:last-child {
  height: 0.65rem !important;
  width:  7rem !important;
}

/* Stagger animation delays */
.chkApp .appSkeletonTableRow:nth-child(2) .appSkeleton { animation-delay: 80ms !important; }
.chkApp .appSkeletonTableRow:nth-child(3) .appSkeleton { animation-delay: 160ms !important; }
.chkApp .appSkeletonTableRow:nth-child(4) .appSkeleton { animation-delay: 240ms !important; }
.chkApp .appSkeletonTableRow:nth-child(n+5) .appSkeleton { animation-delay: 300ms !important; }

