  animation: _kpiCardIn 280ms cubic-bezier(0.22,0.61,0.36,1) both !important;
}

.chkApp .kpiCard:nth-child(1) { animation-delay:  0ms !important; }
.chkApp .kpiCard:nth-child(2) { animation-delay: 45ms !important; }
.chkApp .kpiCard:nth-child(3) { animation-delay: 90ms !important; }
.chkApp .kpiCard:nth-child(4) { animation-delay:130ms !important; }

/* Number reveal — count-up simulation via opacity */
