  from { opacity: 0; transform: translateY(3px); }
  to   { opacity: 1; transform: translateY(0); }
}

.chkApp .kpiCard .sapMTitle.appSkeletonReveal {
  animation: _numReveal 320ms cubic-bezier(0.22,0.61,0.36,1) both !important;
