}

/* Table rows appear */
@keyframes _rowIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.chkApp .searchResultsTable .sapMListTblRow {
  animation: _rowIn 180ms ease both !important;
}

.chkApp .searchResultsTable .sapMListTblRow:nth-child(1)  { animation-delay:   0ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(2)  { animation-delay:  18ms !important; }
.chkApp .searchResultsTable .sapMListTblRow:nth-child(3)  { animation-delay:  36ms !important; }
