/* ══════════════════════════════════════════════════════════════
   CH 10 · infoCard focus / drag / reveal animation
   ══════════════════════════════════════════════════════════════ */

/* Focus ring on grid item */
.chkApp .infoCardGrid .sapFGLI:focus {
  outline: none !important;
}

.chkApp .infoCardGrid .sapFGLI:focus .infoCardTile.mushroomCard {
  box-shadow:   0 0 0 2px var(--hz-accent, #0070F2) !important;
  border-radius:0.875rem !important;
}

.chkApp .infoCardGrid .sapFGLI:focus-within .infoCardTile.mushroomCard {
  box-shadow:   0 0 0 2px rgba(0,112,242,0.40) !important;
}

/* Drag cursor */
.chkApp .infoCardGrid .sapFGLI[draggable="true"] {
  cursor: grab !important;
}

.chkApp .infoCardGrid .sapFGLI:active {
  cursor: grabbing !important;
}

/* Reveal animation */
@keyframes _infoCardIn {
  from { opacity: 0; transform: scale(0.97) translateY(4px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

.chkApp .infoCardGrid .sapFGLI {
  animation: _infoCardIn 220ms cubic-bezier(0.22,0.61,0.36,1) both !important;
}

.chkApp .infoCardGrid .sapFGLI:nth-child(1)  { animation-delay:  0ms !important; }
.chkApp .infoCardGrid .sapFGLI:nth-child(2)  { animation-delay: 30ms !important; }
.chkApp .infoCardGrid .sapFGLI:nth-child(3)  { animation-delay: 55ms !important; }
.chkApp .infoCardGrid .sapFGLI:nth-child(4)  { animation-delay: 80ms !important; }
.chkApp .infoCardGrid .sapFGLI:nth-child(n+5){ animation-delay:100ms !important; }

